INSERT INTO public.assessments (kind, unit_id, title, unit_numbers, question_count, time_limit_minutes, max_attempts, is_open)
SELECT 'pretest', u.id, 'แบบทดสอบก่อนเรียน: ' || u.title, ARRAY[u.number], 10, NULL, 1, true
FROM public.units u WHERE u.number = 1
ON CONFLICT (kind, unit_id) DO UPDATE SET title = EXCLUDED.title, question_count = EXCLUDED.question_count;
INSERT INTO public.assessments (kind, unit_id, title, unit_numbers, question_count, time_limit_minutes, max_attempts, is_open)
SELECT 'posttest', u.id, 'แบบทดสอบหลังเรียน: ' || u.title, ARRAY[u.number], 10, 20, 3, true
FROM public.units u WHERE u.number = 1
ON CONFLICT (kind, unit_id) DO UPDATE SET title = EXCLUDED.title, question_count = EXCLUDED.question_count, max_attempts = EXCLUDED.max_attempts;

INSERT INTO public.assignments (unit_id, kind, title, instructions_md, max_score, rubric)
SELECT u.id, 'worksheet', 'ใบงานที่ 1 วิเคราะห์ธุรกิจพาณิชย์บนสื่อสังคมออนไลน์', '## จุดประสงค์

เพื่อให้ผู้เรียนวิเคราะห์ร้านค้าบนสื่อสังคมออนไลน์ที่มีอยู่จริง และวางแนวคิดธุรกิจออนไลน์ของตนเองได้อย่างละเอียด รอบคอบ

## ขั้นตอนการปฏิบัติ

### ตอนที่ 1 วิเคราะห์ร้านค้าตัวอย่าง
1. เลือกร้านค้าออนไลน์ของไทย 1 ร้าน (เช่น ร้านเสื้อผ้า ร้านขนมพื้นเมือง หรือสินค้า OTOP) ที่ขายผ่านสื่อสังคมออนไลน์อย่างน้อย 2 ช่องทาง
2. ระบุชื่อร้าน ช่องทางที่ใช้ (เช่น Facebook, TikTok Shop, LINE OA, Shopee) และรูปแบบธุรกิจ (ผลิตเอง ซื้อมาขายไป Dropship Pre-order ไลฟ์คอมเมิร์ซ ฯลฯ)
3. วิเคราะห์ว่าร้านสร้างความน่าเชื่อถืออย่างไร (ข้อมูลร้าน รีวิว นโยบายคืนสินค้า DBD Registered ฯลฯ)
4. ตรวจสอบว่ามีจุดใดที่อาจเสี่ยงต่อการขัดกฎหมายหรือจริยธรรม (เช่น โพสต์ข้อมูลลูกค้า โฆษณาเกินจริง) และเสนอแนวทางแก้ไข

### ตอนที่ 2 วางแนวคิดธุรกิจของตนเอง
1. กำหนดสินค้าที่ต้องการขาย และรูปแบบธุรกิจที่เลือก พร้อมเหตุผล
2. จัดทำข้อมูลลูกค้าเป้าหมาย (Persona) 1 คน ระบุอายุ อาชีพ แพลตฟอร์มที่ใช้ ปัญหา และเหตุผลที่จะซื้อ
3. ระบุกฎหมายอย่างน้อย 3 ฉบับที่เกี่ยวข้องกับธุรกิจของตนและสิ่งที่ต้องปฏิบัติ
4. จัดทำรายการตรวจสอบ (Checklist) ความละเอียด รอบคอบ อย่างน้อย 5 ข้อสำหรับธุรกิจของตน

## สิ่งที่ต้องส่ง

- รายงานความยาว 2–4 หน้า (พิมพ์หรือเขียนด้วยลายมือที่อ่านง่าย) พร้อมภาพหน้าจอประกอบตอนที่ 1 โดย **ปิดบังข้อมูลส่วนบุคคลของผู้อื่น**
- ส่งเป็นไฟล์ภาพหรือ PDF ขนาดไม่เกิน 10 MB หรือส่งเป็นลิงก์ (เช่น Google Docs / Canva) ที่เปิดสิทธิ์ให้ครูเข้าดูได้', 20, '[{"criterion":"การวิเคราะห์ร้านค้าตัวอย่าง","max":5,"description":"ระบุช่องทาง รูปแบบธุรกิจ และวิธีสร้างความน่าเชื่อถือของร้านได้ครบถ้วน มีหลักฐานภาพหน้าจอประกอบ"},{"criterion":"แนวคิดธุรกิจและข้อมูลลูกค้าเป้าหมาย","max":5,"description":"เลือกสินค้าและรูปแบบธุรกิจพร้อมเหตุผลที่สมเหตุสมผล Persona มีรายละเอียดครบและสอดคล้องกับแพลตฟอร์ม"},{"criterion":"ความรู้ด้านกฎหมายและจริยธรรม","max":5,"description":"ระบุกฎหมายที่เกี่ยวข้องได้ถูกต้องอย่างน้อย 3 ฉบับ อธิบายสิ่งที่ต้องปฏิบัติและประเด็นจริยธรรมได้ชัดเจน"},{"criterion":"ความละเอียด รอบคอบ และความถูกต้องของงาน","max":5,"description":"Checklist ครบอย่างน้อย 5 ข้อและนำไปใช้ได้จริง ข้อมูลถูกต้อง ปิดบังข้อมูลส่วนบุคคล ส่งงานครบและตรงเวลา"}]'::jsonb
FROM public.units u WHERE u.number = 1;

-- Unit 2: แพลตฟอร์มและการตั้งร้านค้าบนสื่อสังคมออนไลน์
