SELECT u.id, 'ข้อใดเป็นองค์ประกอบสำคัญที่ควรระบุในรายละเอียดสินค้า (Product Description) เพื่อลดอัตราการคืนสินค้า?', '["ประวัติชีวิตส่วนตัวของเจ้าของร้าน","ขนาด น้ำหนัก วัสดุ และตารางเทียบไซส์ที่ชัดเจน","คำกลอนและบทกวีเกี่ยวกับสินค้า","คำรับรองว่าสินค้าไม่มีวันชำรุดเสียหายตลอดชีวิต"]'::jsonb, 1, 'ข้อมูลขนาด น้ำหนัก และสเปกที่ชัดเจนช่วยให้ลูกค้าเลือกซื้อได้ถูกต้องตรงตามความต้องการ'
FROM public.units u WHERE u.number = 2;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ข้อความโฆษณาในข้อใดมีความเสี่ยงผิดกฎหมายและนโยบายแพลตฟอร์มมากที่สุด?', '["เสื้อยืดผลิตจากผ้าคอตตอน 100% สวมใส่สบาย ระบายอากาศได้ดี","ครีมบำรุงผิวผสมวิตามินอี ช่วยให้ผิวชุ่มชื้นตลอดวัน","เซรั่มสลายฝ้าถาวร เห็นผล 100% ภายใน 3 ชั่วโมง ปลอดภัยไร้ผลข้างเคียง","กระเป๋าผ้าแคนวาสขนาด 14x16 นิ้ว รับน้ำหนักได้ 5 กิโลกรัม"]'::jsonb, 2, 'การเคลมสรรพคุณเกินจริงและรับประกันผล 100% ขัดต่อกฎหมาย อย. และ พ.ร.บ.คุ้มครองผู้บริโภค'
FROM public.units u WHERE u.number = 2;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การใส่ข้อมูลคำถามที่พบบ่อย (FAQ) ไว้ในหน้ารายการสินค้า มีประโยชน์หลักด้านใด?', '["เพิ่มพื้นที่โฆษณาของแพลตฟอร์ม","ช่วยให้ลูกค้าตัดสินใจซื้อได้ทันที ลดภาระการตอบแชทของแอดมิน","ทำให้สินค้าไม่ถูกหักค่าธรรมเนียม","ทำให้ไม่ต้องส่งสินค้าตามรอบเวลา"]'::jsonb, 1, 'FAQ ช่วยตอบข้อสงสัยที่พบบ่อย ทำให้ลูกค้าตัดสินใจสั่งซื้อได้รวดเร็วขึ้น'
FROM public.units u WHERE u.number = 2;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'หากร้านค้าจำหน่ายสินค้าประเภทอาหารแปรรูป สิ่งใดที่จำเป็นต้องแสดงบนภาพหรือคำบรรยายสินค้าอย่างรอบคอบ?', '["รูปถ่ายโรงงานขนาดใหญ่","เลขสารบบอาหาร (อย.), วันผลิต, วันหมดอายุ และข้อมูลสารก่อภูมิแพ้","รายชื่อลูกค้าที่เคยสั่งซื้อทั้งหมด","ยอดเงินสะสมในบัญชีร้านค้า"]'::jsonb, 1, 'เลข อย. วันหมดอายุ และสารก่อภูมิแพ้เป็นข้อมูลสำคัญตามกฎหมายที่คุ้มครองผู้บริโภค'
FROM public.units u WHERE u.number = 2;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'กลยุทธ์ Multi-channel Presence ในการทำโซเชียลคอมเมิร์ซหมายถึงข้อใด?', '["การเปิดบัญชีร้านค้าบนแพลตฟอร์มเดียวแต่ใช้โทรศัพท์หลายเครื่อง","การมีหน้าร้านบนหลายแพลตฟอร์มเพื่อเชื่อมโยงการหาลูกค้าใหม่และการรักษาลูกค้าเดิม","การเปลี่ยนชื่อร้านทุกเดือนตามเทศกาล","การขายสินค้าโดยไม่เปิดเผยตัวตนในโลกออนไลน์"]'::jsonb, 1, 'Multi-channel คือการใช้จุดเด่นของหลายแพลตฟอร์มทำงานร่วมกันอย่างเป็นระบบ'
FROM public.units u WHERE u.number = 2;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ข้อใดคือพฤติกรรมการซื้อที่พบได้บ่อยมากที่สุดบนแพลตฟอร์ม TikTok Shop?', '["การศึกษาเปรียบเทียบสเปกอย่างละเอียดเป็นเวลาหลายสัปดาห์","การตัดสินใจซื้ออย่างรวดเร็วจากอารมณ์และการกระตุ้นผ่านคลิปหรือไลฟ์ (Impulse Buying)","การประมูลราคาสินค้ามือสองแบบยื่นซอง","การสั่งซื้อสินค้าล่วงหน้าเป็นระยะเวลา 1 ปี"]'::jsonb, 1, 'วิดีโอสั้นและการไลฟ์ช่วยเร่งการตัดสินใจซื้อแบบทันทีทันใด (Impulse Buying)'
FROM public.units u WHERE u.number = 2;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ก่อนกดยืนยันการลงรายการสินค้า ผู้ขายที่ทำงานด้วยความรอบคอบควรตรวจสอบสิ่งใดเป็นพิเศษ?', '["ราคาขาย ยอดสต็อกคงเหลือ และตัวเลือกสินค้า (สี/ขนาด)","ความเร็วอินเทอร์เน็ตของเครื่องคอมพิวเตอร์","จำนวนผู้เข้าชมเว็บไซต์คู่แข่ง","สภาพอากาศในวันจัดส่ง"]'::jsonb, 0, 'การตรวจสอบราคา สต็อก และตัวเลือกสินค้าป้องกันการตั้งราคาผิดพลาดและการขายสินค้าเกินสต็อก'
FROM public.units u WHERE u.number = 2;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การระบุเงื่อนไขการรับประกันและการเปลี่ยนสินค้าที่ชัดเจน ส่งผลดีต่อร้านค้าอย่างไร?', '["ทำให้ลูกค้าไม่กล้าติดต่อร้านค้าอีก","สร้างความน่าเชื่อถือและลดข้อพิพาทเมื่อสินค้ามีปัญหา","ทำให้ร้านไม่ต้องรับผิดชอบกรณีส่งของผิด","เพิ่มขั้นตอนให้ลูกค้าคืนสินค้ายากขึ้น"]'::jsonb, 1, 'เงื่อนไขที่ชัดเจนช่วยสร้างความมั่นใจให้ผู้ซื้อและกำหนดกรอบแนวทางปฏิบัติเมื่อเกิดปัญหา'
FROM public.units u WHERE u.number = 2;

