INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ข้อใดคือสิ่งที่ผู้ขายที่มีความละเอียด รอบคอบ ควรทำเมื่อจัดส่งสินค้าประเภทแก้วหรือเซรามิก?', '["ห่อด้วยกระดาษหนังสือพิมพ์ 1 แผ่นแล้วใส่ซองพลาสติก","ห่อบับเบิ้ลหนาหลายชั้น เสริมมุมกล่อง และติดป้าย ''ระวังแตก (Fragile)'' อย่างเด่นชัด","ไม่จำเป็นต้องป้องกันเพราะขนส่งมีประกันอยู่แล้ว","ใส่หินลงไปในกล่องเพื่อถ่วงน้ำหนัก"]'::jsonb, 1, 'การกันกระแทกอย่างหนาแน่นและติดสติกเกอร์ระวังแตกช่วยลดโอกาสการเสียหายระหว่างขนย้าย'
