INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การเลือกใช้กล่องพัสดุที่มีขนาดใหญ่เกินตัวสินค้า ส่งผลเสียในข้อใดมากที่สุด?', '["ทำให้สินค้าดูมีราคาแพงขึ้น","เปลืองต้นทุนค่ากล่อง ค่าวัสดุกันกระแทก และเสี่ยงเสียค่าส่งตามขนาดปริมาตรแพงเกินจริง","ทำให้พัสดุจัดส่งถึงเร็วเกินไป","ทำให้เทปกาวติดแน่นขึ้น"]'::jsonb, 1, 'กล่องใหญ่เกินไปทำให้เสียค่ากล่อง ค่าน้ำหนักปริมาตร และของข้างในมีพื้นที่ขยับจนเกิดความเสียหายได้ง่าย'
FROM public.units u WHERE u.number = 4;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ระบบ Drop-off พัสดุของร้านค้าออนไลน์หมายถึงสิ่งใด?', '["การโยนพัสดุลงในแม่น้ำ","การที่ผู้ขายนำพัสดุที่พิมพ์ใบปะหน้าเรียบร้อยแล้วไปหย่อนไว้ที่จุดรับพัสดุโดยไม่ต้องรอคีย์ข้อมูลใหม่","การให้ลูกค้ามารับสินค้าที่หน้าร้านเอง","การยกเลิกการส่งสินค้าทั้งหมด"]'::jsonb, 1, 'Drop-off คือการนำพัสดุที่มีบาร์โค้ดแล้วไปสแกนส่งที่สาขาได้อย่างรวดเร็ว ไม่ต้องรอพนักงานพิมพ์ที่อยู่ใหม่'
FROM public.units u WHERE u.number = 4;

INSERT INTO public.assessments (kind, unit_id, title, unit_numbers, question_count, time_limit_minutes, max_attempts, is_open)
SELECT 'pretest', u.id, 'แบบทดสอบก่อนเรียน: ' || u.title, ARRAY[u.number], 10, NULL, 1, true
FROM public.units u WHERE u.number = 4
ON CONFLICT (kind, unit_id) DO UPDATE SET title = EXCLUDED.title, question_count = EXCLUDED.question_count;
INSERT INTO public.assessments (kind, unit_id, title, unit_numbers, question_count, time_limit_minutes, max_attempts, is_open)
SELECT 'posttest', u.id, 'แบบทดสอบหลังเรียน: ' || u.title, ARRAY[u.number], 10, 20, 3, true
FROM public.units u WHERE u.number = 4
ON CONFLICT (kind, unit_id) DO UPDATE SET title = EXCLUDED.title, question_count = EXCLUDED.question_count, max_attempts = EXCLUDED.max_attempts;

INSERT INTO public.assignments (unit_id, kind, title, instructions_md, max_score, rubric)
SELECT u.id, 'worksheet', 'ใบงานที่ 4: วางแผนการเลือกบริษัทขนส่งและการคำนวณต้นทุนค่าจัดส่งสินค้า', '### จุดประสงค์
เพื่อให้นักศึกษาสามารถเปรียบเทียบผู้ให้บริการขนส่ง คำนวณน้ำหนักจริงเทียบกับน้ำหนักตามปริมาตร และวางแผนบรรจุภัณฑ์สำหรับสินค้าออนไลน์ได้อย่างแม่นยำ

### ขั้นตอนการปฏิบัติงาน
1. เลือกสินค้า 1 ชนิด พร้อมระบุขนาดจริง (กว้าง x ยาว x สูง เป็น ซม.) และน้ำหนักจริง (กก.)
2. คำนวณน้ำหนักตามปริมาตร (Dimensional Weight) โดยใช้สูตรมาตรฐาน และเปรียบเทียบเพื่อหาน้ำหนักที่นำไปคิดค่าขนส่ง
3. คัดเลือกบริษัทขนส่ง 2 แห่งที่เหมาะสมกับสินค้านี้ พร้อมเปรียบเทียบอัตราค่าส่ง ระยะเวลา และเงื่อนไขบริการ
4. ออกแบบขั้นตอนการแพ็กเกจจิ้ง (Packaging Plan):
   - ขนาดกล่องที่ใช้ (เบอร์กล่อง)
   - ชนิดของวัสดุกันกระแทก
   - การปิดผนึกและการติดป้ายเตือน
5. ร่างใบปะหน้าพัสดุ (Shipping Label) จำลองที่มีข้อมูลครบถ้วนถูกต้องตามระเบียบขนส่ง
6. จัดทำรายงานเป็นไฟล์ PDF แนบส่งในระบบ (ขนาดไม่เกิน 10 MB)', 20, '[{"criterion":"ความถูกต้องของการคำนวณ Dimensional Weight","max":5,"description":"แสดงขั้นตอนและสูตรการคำนวณถูกต้อง เปรียบเทียบน้ำหนักจริงกับน้ำหนักตามปริมาตรได้แม่นยำ"},{"criterion":"ความสมเหตุสมผลของการเลือกบริษัทขนส่งและบรรจุภัณฑ์","max":5,"description":"เปรียบเทียบผู้ให้บริการได้อย่างมีหลักการ และเลือกกล่องกับวัสดุกันกระแทกได้เหมาะสมกับตัวสินค้า"},{"criterion":"ความละเอียด รอบคอบ ของข้อมูลบนใบปะหน้าพัสดุ","max":5,"description":"มีข้อมูลผู้ส่ง ผู้รับ รหัสไปรษณีย์ และรายละเอียดพัสดุครบถ้วน ถูกต้องตามระเบียบ"},{"criterion":"การจัดทำรูปเล่มและความเป็นระเบียบเรียบร้อย","max":5,"description":"นำเสนอชัดเจน มีแผนผังประกอบ สวยงาม และส่งตรงเวลา"}]'::jsonb
FROM public.units u WHERE u.number = 4;

-- Unit 5: บริการหลังการขายและการจัดการลูกค้าสัมพันธ์ (CRM)
INSERT INTO public.units (number, title, description, objectives, published)
VALUES (5, 'บริการหลังการขายและการจัดการลูกค้าสัมพันธ์ (CRM)', 'การสื่อสารผ่านแชท การรับมือข้อร้องเรียน นโยบายเปลี่ยน/คืนสินค้า การบริหารรีวิว กฎหมายคุ้มครองผู้บริโภค และพื้นฐาน PDPA', ARRAY['อธิบายหลักการสื่อสารและการบริการลูกค้าผ่านช่องทางแชทได้อย่างมืออาชีพ', 'มีทักษะในการรับมือกับข้อร้องเรียนและแก้ไขปัญหาเฉพาะหน้าด้วยความละเอียด รอบคอบ', 'ร่างนโยบายการรับประกันและการเปลี่ยน/คืนสินค้าที่ชัดเจนและเป็นธรรมได้', 'ปฏิบัติตามแนวทางกฎหมายคุ้มครองผู้บริโภคและ พ.ร.บ.คุ้มครองข้อมูลส่วนบุคคล (PDPA)'], true)
