SELECT u.id, 'เมื่อลูกค้าส่งข้อความร้องเรียนด้วยอารมณ์ไม่พอใจในช่องแชท สิ่งแรกที่แอดมินควรทำตาม HEAR Model คือข้อใด?', '["ส่งสติกเกอร์หัวเราะเพื่อคลายเครียด","รับฟังอย่างตั้งใจ แสดงความเข้าอกเข้าใจ และขออภัยในความไม่สะดวกโดยไม่โต้เถียง","บล็อกผู้ใช้งานทันที","ส่งข้อความตักเตือนลูกค้าเรื่องมารยาท"]'::jsonb, 1, 'ตามหลัก HEAR ต้องรับฟัง (Hear) แสดงความเข้าใจ (Empathize) และขออภัย (Apologize) ก่อนเสนอทางแก้ไข'
FROM public.units u WHERE u.number = 5;
