SELECT u.id, 'การกระทำใดต่อข้อมูลส่วนบุคคลของลูกค้า (ชื่อ ที่อยู่ เบอร์โทร) ที่ถือว่าละเมิดกฎหมาย PDPA?', '["ใช้ข้อมูลที่อยู่เพื่อพิมพ์ใบปะหน้าพัสดุจัดส่งสินค้าตามคำสั่งซื้อ","นำเบอร์โทรศัพท์ของลูกค้าไปขายต่อให้ตัวแทนขายประกันโดยไม่ได้รับความยินยอม","จัดเก็บข้อมูลคำสั่งซื้อไว้ในระบบคลาวด์ที่มีรหัสผ่านป้องกัน","โทรศัพท์ยืนยันที่อยู่จัดส่งสินค้าตามที่ลูกค้าระบุไว้"]'::jsonb, 1, 'การนำข้อมูลส่วนบุคคลไปขายต่อหรือใช้ผิดวัตถุประสงค์โดยไม่ได้รับความยินยอมเป็นการละเมิด PDPA ร้ายแรง'
FROM public.units u WHERE u.number = 5;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'เมื่อได้รับรีวิว 1 ดาวพร้อมข้อความต่อว่าสินค้ามีตำหนิ แนวทางตอบกลับอย่างมืออาชีพคือข้อใด?', '["ลบคอมเมนต์ทิ้งและบล็อกลูกค้า","ตอบโต้ว่าลูกค้าน่าจะทำพังเอง","ตอบขออภัยอย่างสุภาพ แสดงความรับผิดชอบ และเชิญให้ติดต่อช่องทางแชทเพื่อส่งเคลมสินค้าชิ้นใหม่","ไม่ตอบอะไรเลยเพราะเป็นเรื่องปกติของการค้าขาย"]'::jsonb, 2, 'การขออภัยและแสดงความรับผิดชอบต่อหน้ารีวิวสาธารณะช่วยแสดงความเป็นมืออาชีพแก่ลูกค้าท่านอื่นที่เข้ามาอ่าน'
FROM public.units u WHERE u.number = 5;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'กรณีร้านค้าส่งสินค้าผิดสีหรือผิดขนาดให้ลูกค้า ใครควรเป็นผู้รับผิดชอบค่าใช้จ่ายในการจัดส่งเปลี่ยนสินค้า?', '["ลูกค้าต้องรับผิดชอบค่าส่งทั้งไปและกลับ","ร้านค้ารับผิดชอบค่าใช้จ่ายในการจัดส่งทั้งหมดทั้งส่งคืนและส่งใหม่","บริษัทขนส่งต้องเป็นผู้จ่าย","หารครึ่งคนละครึ่งระหว่างลูกค้ากับร้านค้า"]'::jsonb, 1, 'ความผิดพลาดเกิดจากร้านค้า ร้านค้าจึงต้องแสดงความรับผิดชอบค่าจัดส่งเปลี่ยนสินค้าทั้งหมด 100%'
FROM public.units u WHERE u.number = 5;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ทำไมร้านค้าจึงมักขอความร่วมมือให้ลูกค้าถ่ายคลิปวิดีโอขณะเปิดกล่องพัสดุ (Unboxing Video)?', '["เพื่อนำคลิปไปโพสต์ลง TikTok โดยไม่ต้องขออนุญาต","เพื่อใช้เป็นหลักฐานที่ชัดเจนในการตรวจสอบว่าสินค้าชำรุดจากการขนส่งหรือได้รับไม่ครบจริง","เพื่อให้ลูกค้าเสียเวลา","เพื่อป้องกันไม่ให้ลูกค้าทำเรื่องคืนสินค้าได้"]'::jsonb, 1, 'วิดีโอการแกะกล่องเป็นหลักฐานสำคัญที่ช่วยยืนยันสภาพสินค้า ณ เวลาส่งมอบ ลดข้อโต้แย้งระหว่างผู้ซื้อ ผู้ขาย และขนส่ง'
FROM public.units u WHERE u.number = 5;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ปรากฏการณ์ Service Recovery Paradox ในการบริหารลูกค้าสัมพันธ์ หมายถึงสิ่งใด?', '["การที่ลูกค้าที่ได้รับสินค้าถูกต้องไม่ยอมกลับมาซื้อซ้ำ","การที่ลูกค้าที่เคยเจอปัญหาได้รับการแก้ไขอย่างดีเยี่ยมจนกลายเป็นผู้ที่มีความภักดีต่อแบรนด์มากกว่าเดิม","การที่ร้านค้าลดราคาสินค้าจนขาดทุน","การที่แอดมินลาออกพร้อมกัน"]'::jsonb, 1, 'คือภาวะที่ลูกค้ารู้สึกประทับใจความรับผิดชอบในการแก้ปัญหาของแบรนด์ จนรักและภักดีต่อแบรนด์มากกว่าเดิม'
FROM public.units u WHERE u.number = 5;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ข้อใดเป็นตัวอย่างของการตั้งค่าข้อความตอบกลับอัตโนมัติ (Auto-reply) ที่มีประโยชน์ต่อลูกค้ามากที่สุด?', '["''สวัสดี เดี๋ยวมาตอบ''","''สวัสดีครับ ร้านค้าเปิดทำการ 09.00-18.00 น. หากต้องการสั่งซื้อสามารถเลือกชมสินค้าในตะกร้าได้เลยครับ''","''อย่าทักซ้ำ แอดมินกำลังนอน''","''ทักมาทำไม''"]'::jsonb, 1, 'ข้อความอัตโนมัติที่ดีต้องแจ้งเวลาทำการ และให้ช่องทางที่ลูกค้าสามารถดูข้อมูลหรือสั่งซื้อได้ด้วยตนเองทันที'
FROM public.units u WHERE u.number = 5;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การบรอดแคสต์ (Broadcast) ข้อความโปรโมชันใน LINE OA ข้อใดเป็นแนวปฏิบัติที่เหมาะสม?', '["ส่งข้อความบรอดแคสต์ทุกๆ 1 ชั่วโมงเพื่อย้ำเตือนลูกค้า","ส่งสัปดาห์ละ 1–2 ครั้ง ในช่วงเวลาที่เหมาะสม และคัดเลือกเนื้อหาที่เป็นประโยชน์ต่อผู้รับ","ส่งข้อความลูกโซ่ขอให้แชร์ต่อ 10 คน","ส่งรูปภาพสวัสดีวันจันทร์ถึงวันอาทิตย์ทุกเช้าโดยไม่มีข้อมูลสินค้า"]'::jsonb, 1, 'การบรอดแคสต์บ่อยเกินไปจะทำให้ลูกค้ารู้สึกรำคาญและกดบล็อก (Block) ควรส่งตามความเหมาะสมและมีคุณค่า'
FROM public.units u WHERE u.number = 5;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'สิทธิของผู้บริโภคตามกฎหมายข้อใดที่เกี่ยวข้องโดยตรงกับการได้รับข้อมูลสินค้าอย่างซื่อสัตย์?', '["สิทธิในการซื้อสินค้าโดยไม่ต้องจ่ายเงิน","สิทธิที่จะได้รับข่าวสารรวมทั้งคำพรรณนาคุณภาพที่ถูกต้องและเพียงพอเกี่ยวกับสินค้า","สิทธิในการต่อรองราคาตามใจชอบ","สิทธิในการส่งคืนสินค้าหลังจากใช้งานไปแล้ว 1 ปี"]'::jsonb, 1, 'พ.ร.บ.คุ้มครองผู้บริโภค ให้สิทธิขั้นพื้นฐานในการได้รับข้อมูลและคำพรรณนาคุณภาพที่ถูกต้องตรงความเป็นจริง'
FROM public.units u WHERE u.number = 5;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'พฤติกรรมใดของแอดมินตอบแชทที่แสดงถึงการขาด ''ความละเอียด รอบคอบ''?', '["ทบทวนรายการสินค้าและที่อยู่จัดส่งกับลูกค้าก่อนสรุปยอดเงิน","อ่านข้อความของลูกค้าไม่จบแล้วตอบคำถามผิดประเด็น","บันทึกประวัติการแพ้อาหารหรือความต้องการพิเศษของลูกค้าลงในระบบ","ตรวจสอบสถานะยอดเงินในระบบก่อนแจ้งยืนยันคำสั่งซื้อ"]'::jsonb, 1, 'การไม่อ่านรายละเอียดให้ครบถ้วนทำให้ตอบผิดประเด็นและสร้างความเข้าใจผิดหรือความหงุดหงิดให้แก่ลูกค้า'
FROM public.units u WHERE u.number = 5;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การติดแท็ก (Tagging) สถานะลูกค้าในระบบ CRM หรือ LINE OA มีประโยชน์อย่างไร?', '["เพื่อคิดราคาขายให้แพงขึ้นตามใจชอบ","เพื่อจัดกลุ่มลูกค้า (เช่น ลูกค้า VIP, ลูกค้ารอโอน, ลูกค้าแจ้งเคลม) ทำให้ดูแลได้อย่างตรงจุด","เพื่อให้โทรศัพท์ทำงานเร็วขึ้น","เพื่อลบรายชื่อลูกค้าออกจากระบบอัตโนมัติ"]'::jsonb, 1, 'การติดแท็กช่วยแบ่งกลุ่มลูกค้า (Segmentation) เพื่อการสื่อสารและการบริการที่ตรงกับความต้องการของแต่ละคน'
FROM public.units u WHERE u.number = 5;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'หากร้านค้าทำสินค้าตกหล่นไม่ได้ใส่ลงในกล่องพัสดุ แนวทางแก้ไขปัญหาที่รวดเร็วและถูกต้องที่สุดคือข้อใด?', '["บอกให้ลูกค้ารอสั่งซื้อรอบหน้าแล้วค่อยส่งไปให้","ตรวจสอบภาพหรือประวัติการแพ็ก ขออภัยลูกค้า และรีบจัดส่งสินค้าที่ขาดไปให้ทันทีโดยไม่มีค่าใช้จ่าย","แจ้งว่าลูกค้าทำหล่นหายเองหลังจากแกะกล่อง","เงียบและไม่ตอบแชท"]'::jsonb, 1, 'ต้องตรวจสอบข้อเท็จจริง ขออภัย และรีบส่งสินค้าตามไปให้อย่างเร่งด่วนเพื่อรักษาความรู้สึกของลูกค้า'
FROM public.units u WHERE u.number = 5;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'เอกสาร Privacy Notice หรือนโยบายความเป็นส่วนตัว ควรมีเนื้อหาหลักเกี่ยวกับสิ่งใด?', '["ประวัติความเป็นมาของตระกูลเจ้าของร้าน","วัตถุประสงค์ในการเก็บรวบรวมข้อมูลส่วนบุคคล ระยะเวลาจัดเก็บ และสิทธิของเจ้าของข้อมูล","รายชื่อพนักงานในร้านทุกคนพร้อมเงินเดือน","สูตรลับในการผลิตสินค้า"]'::jsonb, 1, 'Privacy Notice มีไว้เพื่อชี้แจงให้ลูกค้าทราบว่าเก็บข้อมูลอะไร เพื่ออะไร เก็บไว้นานแค่ไหน และมีสิทธิใดบ้างตาม PDPA'
FROM public.units u WHERE u.number = 5;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'เหตุใดการตอบข้อความลูกค้าด้วยความสุภาพและควบคุมอารมณ์จึงเป็นทักษะที่สำคัญอย่างยิ่งในการขายออนไลน์?', '["เพราะบทสนทนาบนโลกดิจิทัลสามารถถูกบันทึกและเผยแพร่สู่สาธารณะได้ตลอดเวลา","เพื่อให้ลูกค้าเกรงใจและยอมจ่ายเงินเพิ่ม","เพราะระบบแชทจะตัดสัญญาณหากพิมพ์คำหยาบ","เพื่อให้ข้อความมีความยาวมากขึ้น"]'::jsonb, 0, 'ข้อความแชทเป็นหลักฐานดิจิทัลที่สามารถถูกแคปหน้าจอไปแชร์ต่อได้ การมีสติและสุภาพจึงช่วยปกป้องชื่อเสียงของแบรนด์'
FROM public.units u WHERE u.number = 5;

INSERT INTO public.assessments (kind, unit_id, title, unit_numbers, question_count, time_limit_minutes, max_attempts, is_open)
SELECT 'pretest', u.id, 'แบบทดสอบก่อนเรียน: ' || u.title, ARRAY[u.number], 10, NULL, 1, true
FROM public.units u WHERE u.number = 5
ON CONFLICT (kind, unit_id) DO UPDATE SET title = EXCLUDED.title, question_count = EXCLUDED.question_count;
INSERT INTO public.assessments (kind, unit_id, title, unit_numbers, question_count, time_limit_minutes, max_attempts, is_open)
SELECT 'posttest', u.id, 'แบบทดสอบหลังเรียน: ' || u.title, ARRAY[u.number], 10, 20, 3, true
FROM public.units u WHERE u.number = 5
ON CONFLICT (kind, unit_id) DO UPDATE SET title = EXCLUDED.title, question_count = EXCLUDED.question_count, max_attempts = EXCLUDED.max_attempts;

INSERT INTO public.assignments (unit_id, kind, title, instructions_md, max_score, rubric)
SELECT u.id, 'worksheet', 'ใบงานที่ 5: จัดทำคู่มือบริการลูกค้าทางแชท นโยบายการคืนสินค้า และแผนรับมือข้อร้องเรียน', '### จุดประสงค์
เพื่อให้นักศึกษาสามารถร่างสคริปต์การสื่อสารบริการลูกค้า ออกแบบนโยบายการรับประกันและการเปลี่ยน/คืนสินค้า และวางแนวทางรับมือข้อร้องเรียนตามหลักความละเอียด รอบคอบ และกฎหมายคุ้มครองผู้บริโภค

### ขั้นตอนการปฏิบัติงาน
1. กำหนดชื่อร้านค้าและสินค้าหลัก 1 ร้าน
2. ร่าง **"สคริปต์มาตรฐานการตอบแชท (Chat Standard Operating Procedure)"** 3 สถานการณ์:
   - การทักทายและตอบคำถามข้อมูลสินค้าเบื้องต้น
   - การสรุปยอด ปิดการขาย และแจ้งช่องทางชำระเงิน
   - การติดตามและแจ้งหมายเลขพัสดุ
3. ร่าง **"นโยบายการรับประกันและการเปลี่ยน-คืนสินค้า (Return & Refund Policy)"** ที่ชัดเจน เป็นธรรม และระบุเงื่อนไขระยะเวลาไว้อย่างรัดกุม
4. จัดทำ **"แผนรับมือข้อร้องเรียน (Crisis & Complaint Handling)"** จำลองสถานการณ์เมื่อลูกค้าได้รับสินค้าชำรุดเสียหาย และเขียนบทสนทนาโต้ตอบตามหลัก HEAR Model
5. ระบุมาตรการในการคุ้มครองข้อมูลส่วนบุคคลของลูกค้า (PDPA Checklist) ที่ร้านค้าจะนำไปปฏิบัติ
6. จัดทำเป็นรายงาน PDF แนบส่งในระบบ (ไม่เกิน 10 MB)', 20, '[{"criterion":"ความเป็นมืออาชีพและความเหมาะสมของสคริปต์ตอบแชท","max":5,"description":"ใช้ภาษาถูกต้อง สุภาพ ชัดเจน สื่อสารตรงประเด็น และสะท้อนตัวตนของแบรนด์"},{"criterion":"ความรัดกุมและเป็นธรรมของนโยบายเปลี่ยน/คืนสินค้า","max":5,"description":"กำหนดเงื่อนไข ขั้นตอน และความรับผิดชอบได้อย่างเป็นธรรม ชัดเจน และสอดคล้องกับกฎหมาย"},{"criterion":"ความละเอียด รอบคอบ ในการแก้ไขข้อร้องเรียน (HEAR Model)","max":5,"description":"แก้ปัญหาเฉพาะหน้าได้อย่างเข้าอกเข้าใจ แสดงความรับผิดชอบ และมีมาตรการคุ้มครองข้อมูล PDPA"},{"criterion":"การจัดรูปเล่มและความคิดสร้างสรรค์","max":5,"description":"จัดรูปแบบน่าอ่าน เป็นระเบียบเรียบร้อย สวยงาม และส่งงานตรงต่อเวลา"}]'::jsonb
FROM public.units u WHERE u.number = 5;

-- Unit 6: การจัดการคลังสินค้าและสต็อกในพาณิชย์บนสื่อสังคมออนไลน์
INSERT INTO public.units (number, title, description, objectives, published)
