INSERT INTO public.lessons (unit_id, position, title, content_md)
SELECT u.id, 1, 'การตั้งรหัสสินค้า (SKU) และระบบบัญชีคุมสินค้า (Stock Card)', '## พื้นฐานการควบคุมสต็อกสินค้าออนไลน์

การจัดการสินค้าคงคลังที่มีประสิทธิภาพช่วยป้องกันสองปัญหาสำคัญ: **"สินค้าขาดมือ (Out of Stock)"** จนเสียโอกาสในการขาย และ **"สินค้าล้นสต็อก (Overstock)"** จนเงินจมและสินค้าหมดอายุ

### 1. การกำหนดรหัสสินค้า SKU (Stock Keeping Unit)
SKU คือรหัสประจำตัวสินค้าที่กำหนดขึ้นเพื่อจำแนกประเภท รุ่น สี และขนาดของสินค้าอย่างเป็นระบบ:
- **ตัวอย่างโครงสร้าง SKU:** `[ประเภท]-[รุ่น]-[สี]-[ขนาด]`
- เช่น เสื้อยืดคอกลม รุ่นคลาสสิก สีขาว ไซส์ L อาจตั้งรหัสเป็น: `TSH-CLS-WH-L`
- รหัส SKU ที่ดีควรสั้น กระชับ สื่อความหมาย และสอดคล้องกันทุกแพลตฟอร์ม

### 2. บัญชีคุมสินค้า (Stock Card) และหลักการ FIFO / FEFO
- **Stock Card:** ตารางบันทึกการเคลื่อนไหวของสินค้าแต่ละ SKU ประกอบด้วย วันที่, เอกสารอ้างอิง, รับเข้า, จ่ายออก, และยอดคงเหลือ
- **FIFO (First-In, First-Out):** สินค้าที่รับเข้ามาก่อนต้องถูกหยิบไปขายก่อน เพื่อป้องกันสินค้าเก่าเก็บ เสื่อมสภาพ หรือตกยุค
- **FEFO (First-Expired, First-Out):** ใช้กับสินค้าที่มีวันหมดอายุ (เช่น เครื่องสำอาง อาหารเสริม) โดยจัดส่งสินค้าที่หมดอายุก่อนออกไปก่อนเสมอ

> 💡 เคล็ดลับ: การติดบาร์โค้ดที่ชั้นวางและตัวสินค้าเพื่อสแกนด้วยโทรศัพท์มือถือขณะหยิบของ จะช่วยลดข้อผิดพลาดในการหยิบสินค้าผิดรุ่นได้เกือบ 100%

> ⚠️ ข้อควรระวัง (ความละเอียด รอบคอบ): อย่าเก็บสินค้าโดยไม่มีป้ายระบุ SKU กำกับ เพราะพนักงานใหม่อาจหยิบสินค้าที่มีลักษณะภายนอกคล้ายกันผิดชิ้น ส่งผลให้ลูกค้าได้รับสินค้าผิดและต้องเสียค่าส่งเปลี่ยนสินค้า'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.lessons (unit_id, position, title, content_md)
SELECT u.id, 2, 'การคำนวณจุดสั่งซื้อใหม่ (Reorder Point) และสต็อกเพื่อความปลอดภัย (Safety Stock)', '## การวางแผนสั่งซื้อสินค้าอย่างแม่นยำ

การสั่งสินค้าเมื่อสต็อกหมดพอดีจะทำให้เกิดช่วงเวลา "ของขาดสต็อก" ในระหว่างที่รอผู้ผลิตส่งของ ดังนั้นจึงต้องคำนวณจุดสั่งซื้อใหม่ล่วงหน้า

### 1. คำศัพท์สำคัญ
- **ยอดขายเฉลี่ยต่อวัน (Average Daily Demand - D):** จำนวนชิ้นที่ขายได้ใน 1 วัน
- **ระยะเวลารอคอยสินค้า (Lead Time - L):** จำนวนวันที่โรงงานใช้ในการผลิตและจัดส่งสินค้ามาถึงร้าน
- **สต็อกเพื่อความปลอดภัย (Safety Stock - SS):** สต็อกสำรองเผื่อกรณีขายดีผิดปกติหรือโรงงานส่งของล่าช้า

### 2. สูตรการคำนวณจุดสั่งซื้อใหม่ (Reorder Point - ROP)

$$\text{Reorder Point (ROP)} = (\text{ยอดขายต่อวัน} \times \text{ระยะเวลารอคอย}) + \text{สต็อกเพื่อความปลอดภัย}$$
$$\text{ROP} = (D \times L) + SS$$

### ตัวอย่างการคำนวณ:
ร้านขายเซรั่มบำรุงผิวมียอดขายเฉลี่ย **วันละ 20 ขวด** โรงงานใช้เวลาผลิตและส่งของ **7 วัน** ทางร้านกำหนดสต็อกสำรองเพื่อความปลอดภัยไว้ **50 ขวด**
$$\text{ROP} = (20 \times 7) + 50 = 140 + 50 = 190 \text{ ขวด}$$
**ความหมาย:** เมื่อสต็อกเซรั่มในคลังลดลงมาเหลือแตะ **190 ขวด** ผู้จัดการร้านต้องทำการออกใบสั่งซื้อสินค้าล็อตใหม่ทันที เพื่อไม่ให้เกิดภาวะสินค้าขาดมือ

> 💡 เคล็ดลับ: ในช่วงเทศกาลแคมเปญใหญ่ (เช่น ดับเบิ้ลเดย์ 9.9 หรือ 11.11) ยอดขายเฉลี่ยต่อวันอาจพุ่งขึ้น 3–5 เท่า ต้องปรับเพิ่มค่า Safety Stock ล่วงหน้าอย่างน้อย 1 เดือน

> ⚠️ ข้อควรระวัง (ความละเอียด รอบคอบ): การคำนวณ Lead Time ต้องเผื่อวันหยุดยาวของโรงงานหรือด่านศุลกากร (กรณีนำเข้าสินค้าจากต่างประเทศ) หากคำนวณคลาดเคลื่อน ร้านค้าอาจต้องปิดรับออเดอร์และเสียคะแนนประเมินของร้านบนแพลตฟอร์ม'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.lessons (unit_id, position, title, content_md)
SELECT u.id, 3, 'การเชื่อมโยงสต็อกหลายช่องทาง (Multi-channel Sync) และการจัดการ Dead Stock', '## การป้องกันปัญหาสต็อกไม่ตรงกันและการจัดการสินค้าค้างสต็อก

เมื่อเปิดร้านค้าพร้อมกันหลายแพลตฟอร์ม (TikTok Shop, Shopee, Lazada, LINE SHOPPING) ความท้าทายสูงสุดคือการป้องกันการ **"ขายสินค้าเกินสต็อกที่มีจริง (Overselling)"**

### เครื่องมือซิงค์สต็อกรวม (Multi-channel Inventory Management)
โปรแกรมประเภท Omnichannel ERP เช่น Zort, Page365, หรือ BigSeller ทำหน้าที่:
- **รวมศูนย์สต็อกไว้ที่เดียว (Centralized Inventory):** เมื่อมีคำสั่งซื้อเกิดขึ้นบน Shopee ระบบจะตัดสต็อกบน TikTok Shop และ LINE MyShop ให้ลดลงตามทันทีแบบอัตโนมัติ
- **ตัดปัญหา Overselling:** ไม่ต้องกังวลว่าลูกค้าจะกดซื้อสินค้าชิ้นสุดท้ายพร้อมกันบนคนละแอป
- **รวมใบปะหน้าพัสดุ:** สามารถสั่งพิมพ์ใบส่งของจากทุกช่องทางได้ในหน้าต่างเดียว

### กลยุทธ์การระบายสินค้าค้างสต็อก (Dead Stock)
สินค้าที่เก็บไว้ในคลังนานเกิน 90–180 วันโดยไม่มีการเคลื่อนไหว เรียกว่า Dead Stock ซึ่งทำให้เงินจมและเปลืองพื้นที่จัดเก็บ:
1. **จัดเซ็ตคู่กับสินค้าขายดี (Bundling):** นำสินค้าค้างสต็อกมาจัดเป็นแพ็กคู่กับสินค้าขายดีในราคาพิเศษ
2. **จัดโปรโมชัน Flash Sale ขาดทุนกำไร:** ยอมลดราคาเพื่อดึงเงินสดกลับมาหมุนเวียน
3. **ใช้เป็นของแถมพรีเมียม (Free Gift):** กำหนดเงื่อนไขซื้อครบ 500 หรือ 1,000 บาท แถมสินค้าชิ้นนี้ฟรี เพื่อเพิ่มยอดซื้อต่อบิล (AOV)

> 💡 เคล็ดลับ: ตรวจนับสต็อกจริง (Physical Stock Count) อย่างน้อยเดือนละ 1 ครั้ง เพื่อเปรียบเทียบกับตัวเลขในระบบและปรับปรุงข้อมูลให้ตรงกันเสมอ

> ⚠️ ข้อควรระวัง (ความละเอียด รอบคอบ): หากเกิดกรณี Overselling แล้วร้านค้ากดยกเลิกออเดอร์ของลูกค้า แพลตฟอร์มอย่าง Shopee หรือ TikTok Shop จะตัดคะแนนร้านค้า (Penalty Points) และอาจถูกลดการมองเห็นหรือระงับการจัดส่งชั่วคราว'
FROM public.units u WHERE u.number = 6;

INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'สูตรในการคำนวณจุดสั่งซื้อใหม่ (Reorder Point - ROP) ที่ถูกต้องคือข้อใด?', '["(ยอดขายต่อวัน x ระยะเวลารอคอย) + สต็อกเพื่อความปลอดภัย","ยอดขายต่อวัน หารด้วย จำนวนวันในหนึ่งเดือน","สต็อกคงเหลือ ลบด้วย สต็อกเพื่อความปลอดภัย","(ระยะเวลารอคอย x 100) / ยอดขายรวม"]'::jsonb, 0, 'ROP = (Daily Demand x Lead Time) + Safety Stock เป็นสูตรมาตรฐานในการสั่งซื้อสินค้าก่อนของจะหมด'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'หากร้านมียอดขายเฉลี่ยวันละ 15 ชิ้น โรงงานใช้เวลาส่งของ 5 วัน และตั้งสต็อกสำรองไว้ 30 ชิ้น จุดสั่งซื้อใหม่ (ROP) คือกี่ชิ้น?', '["75 ชิ้น","105 ชิ้น","120 ชิ้น","150 ชิ้น"]'::jsonb, 1, '(15 x 5) + 30 = 75 + 30 = 105 ชิ้น เมื่อสต็อกเหลือ 105 ชิ้นต้องสั่งทันที'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'หลักการหมุนเวียนสินค้าแบบ FIFO (First-In, First-Out) มีแนวทางปฏิบัติอย่างไร?', '["นำสินค้าที่รับเข้ามาล่าสุดไปขายก่อนเสมอ","นำสินค้าที่รับเข้ามาก่อนไปจัดส่งให้ลูกค้าก่อนเพื่อป้องกันสินค้าเก่าเก็บเสื่อมสภาพ","สุ่มหยิบสินค้าชิ้นใดก็ได้ที่ใกล้มือ","ขายสินค้าชิ้นที่ราคาแพงที่สุดก่อน"]'::jsonb, 1, 'FIFO คือการนำสินค้าล็อตที่เข้ามาก่อนไปจ่ายออกก่อน เพื่อลดปัญหาสินค้าค้างเก่า'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'หลักการ FEFO (First-Expired, First-Out) เหมาะสมที่สุดสำหรับสินค้าประเภทใด?', '["เสื้อผ้าแฟชั่นและเครื่องประดับ","อาหาร อาหารเสริม ยา และเครื่องสำอางที่มีวันหมดอายุชัดเจน","อุปกรณ์อิเล็กทรอนิกส์และสายชาร์จ","เฟอร์นิเจอร์ไม้"]'::jsonb, 1, 'FEFO เน้นปล่อยสินค้าที่จะหมดอายุก่อนออกไปก่อน เหมาะอย่างยิ่งกับสินค้าอุปโภคบริโภคที่มีวันหมดอายุ'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'โครงสร้างรหัสสินค้า SKU ที่ดีควรมีลักษณะอย่างไร?', '["เป็นตัวเลขสุ่มยาว 30 ตัวอักษรที่ไม่สื่อความหมาย","มีโครงสร้างที่ชัดเจน สื่อถึงประเภท รุ่น สี และขนาด ช่วยให้แยกแยะง่าย","ใช้ชื่อจริงของเจ้าของร้านเป็นรหัสสินค้า","เปลี่ยนรหัสสินค้าใหม่ทุกสัปดาห์"]'::jsonb, 1, 'รหัส SKU ที่ดีต้องมีแบบแผน สื่อความหมาย และช่วยให้พนักงานระบุตัวตนสินค้าได้อย่างแม่นยำ'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ปัญหา ''Overselling'' ในการขายสินค้าออนไลน์เกิดขึ้นจากสาเหตุใด?', '["การขายสินค้าในราคาถูกเกินไปจนขาดทุน","การเปิดขายหลายแพลตฟอร์มโดยสต็อกไม่เชื่อมโยงกัน ทำให้ลูกค้ารับคำสั่งซื้อเกินกว่าจำนวนสินค้าที่มีจริงในคลัง","การส่งสินค้าให้ลูกค้าก่อนที่ลูกค้าจะโอนเงิน","การมีสินค้าล้นคลังจนไม่มีที่เก็บ"]'::jsonb, 1, 'Overselling คือการขายของเกินสต็อก เกิดจากการที่สต็อกบนหลายช่องทางไม่ตัดแบบ Real-time'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'เครื่องมือระบบจัดการคลังสินค้าแบบ Multi-channel (เช่น Zort หรือ Page365) ช่วยแก้ปัญหาใดได้ดีที่สุด?', '["ช่วยซิงค์ยอดสต็อกอัตโนมัติข้ามหลายแพลตฟอร์มเมื่อเกิดการซื้อขาย ป้องกันปัญหาสต็อกไม่ตรง","ช่วยลดราคาสินค้าให้ลูกค้าอัตโนมัติ","ช่วยทำความสะอาดคลังสินค้า","ช่วยจดทะเบียนบริษัทให้ฟรี"]'::jsonb, 0, 'ระบบเหล่านี้ช่วยตัดสต็อกส่วนกลางแบบอัตโนมัติทุกครั้งที่มีออเดอร์จากช่องทางใดก็ตาม'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'Dead Stock หมายถึงสินค้าคงคลังประเภทใด?', '["สินค้าที่เพิ่งผลิตเสร็จใหม่จากโรงงาน","สินค้าค้างสต็อกเป็นเวลานานที่ไม่มีการเคลื่อนไหวหรือขายไม่ออก ทำให้เงินจม","สินค้าที่ถูกขโมยไปจากคลัง","สินค้าที่ขายหมดเกลี้ยงภายใน 1 วัน"]'::jsonb, 1, 'Dead Stock คือสินค้าค้างเก่า ขายไม่ออก ส่งผลให้เสียพื้นที่จัดเก็บและสภาพคล่องทางการเงิน'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'วิธีใดต่อไปนี้เหมาะสมในการระบายสินค้าค้างสต็อก (Dead Stock) เพื่อนำเงินสดกลับมาหมุนเวียน?', '["เก็บซ่อนไว้ในคลังต่อไปอีก 5 ปี","จัดเซ็ตโปรโมชันคู่กับสินค้าขายดี (Bundling) หรือจัด Flash Sale ราคาพิเศษ","ปรับขึ้นราคาสินค้าให้แพงขึ้น 3 เท่า","ยกเลิกกิจการทันที"]'::jsonb, 1, 'การจัด Bundling, Flash Sale หรือให้เป็นของแถมช่วยระบายสต็อกและดึงเงินสดกลับคืนมาได้เร็ว'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'บัญชีคุมสินค้า (Stock Card) มีประโยชน์หลักต่อผู้บริหารร้านค้าอย่างไร?', '["ใช้ดูยอดกดไลก์ของเพจ","ใช้บันทึกประวัติการรับเข้า-จ่ายออก และตรวจสอบยอดคงเหลือของสินค้าแต่ละ SKU ได้อย่างโปร่งใส","ใช้ส่งให้ลูกค้าดูเพื่อยืนยันราคา","ใช้สำหรับออกแบบภาพปกสินค้า"]'::jsonb, 1, 'Stock Card แสดงประวัติการเคลื่อนไหวของสินค้าเข้า-ออกและยอดคงเหลือเพื่อความถูกต้องในการตรวจสอบ'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การตรวจนับสินค้าคงคลังจริง (Physical Stock Count) ควรทำเพื่อวัตถุประสงค์ใด?', '["เพื่อกระทบยอดสินค้าจริงบนชั้นวางให้ตรงกับตัวเลขในระบบและค้นหาสินค้าสูญหาย/ชำรุด","เพื่อให้พนักงานได้ออกกำลังกาย","เพื่อปรับราคาขายสินค้าให้แพงขึ้น","เพื่อแจ้งปิดร้านค้าถาวร"]'::jsonb, 0, 'การนับสต็อกจริงช่วยจับความคลาดเคลื่อนระหว่างสต็อกบนระบบกับของจริงบนชั้นวาง'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'สต็อกเพื่อความปลอดภัย (Safety Stock) มีไว้เพื่อป้องกันความเสี่ยงในข้อใด?', '["ป้องกันการถูกขโมยเงินในบัญชีธนาคาร","ป้องกันกรณีที่ยอดขายพุ่งสูงขึ้นกะทันหันหรือโรงงานส่งมอบสินค้าล่าช้ากว่ากำหนด","ป้องกันไม่ให้ลูกค้ากดรีวิว 1 ดาว","ป้องกันการเสียภาษีเงินได้"]'::jsonb, 1, 'Safety Stock คือกันชนสำรองเผื่ออุปสงค์สูงผิดปกติหรือซัพพลายเออร์ส่งของล่าช้า'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'หากเกิดกรณี Overselling แล้วร้านค้าจำเป็นต้องกดยกเลิกคำสั่งซื้อของลูกค้า ผลเสียที่จะเกิดขึ้นต่อร้านคือข้อใด?', '["ร้านค้าจะได้รับโบนัสจากแพลตฟอร์ม","ลูกค้าเสียความรู้สึก และร้านค้าถูกตัดคะแนนความประพฤติ (Penalty) จนอาจถูกลดการมองเห็น","ยอดขายจะเพิ่มขึ้นในวันถัดไป","ไม่มีผลเสียใดๆ เกิดขึ้น"]'::jsonb, 1, 'การยกเลิกออเดอร์ส่งผลเสียต่อความน่าเชื่อถือและทำให้ร้านค้าโดนบทลงโทษจากระบบของแพลตฟอร์ม'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การจัดหมวดหมู่วางสินค้าในคลัง โดยนำสินค้าที่ขายดี (Fast Moving) มาไว้ใกล้จุดแพ็กของ สอดคล้องกับหลักการใด?', '["การลดระยะทางและเวลาในการเดินหยิบสินค้า เพิ่มประสิทธิภาพการทำงาน","การซ่อนสินค้าไม่ให้ใครเห็น","การทำให้คลังสินค้าดูรกขึ้น","การประหยัดไฟในคลัง"]'::jsonb, 0, 'การวางสินค้าขายดีไว้ใกล้จุดแพ็กช่วยลดระยะทางเดินหยิบของและเร่งความเร็วในการทำงาน'
FROM public.units u WHERE u.number = 6;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ข้อใดเป็นพฤติกรรมที่แสดงถึงความละเอียด รอบคอบ ในการจัดการสต็อกสินค้าออนไลน์?', '["เดาจำนวนสินค้าคงเหลือด้วยสายตาโดยไม่นับ","อัปเดตยอดรับเข้า-จ่ายออกในระบบทันทีทุกครั้ง และตรวจสอบสภาพสินค้าก่อนจัดเก็บเข้าชั้นวาง","ปล่อยให้สินค้าวางปะปนกันโดยไม่แยกไซส์","ไม่บันทึกสินค้าที่นำออกมาเป็นของแถม"]'::jsonb, 1, 'การบันทึกข้อมูลแบบ Real-time และการตรวจสอบสภาพสินค้าสะท้อนความละเอียดรอบคอบในการทำงาน'
FROM public.units u WHERE u.number = 6;

