INSERT INTO public.assignments (unit_id, kind, title, instructions_md, max_score, rubric)
SELECT u.id, 'worksheet', 'ใบงานที่ 6: ออกแบบระบบรหัสสินค้า SKU และวางแผนการคำนวณจุดสั่งซื้อใหม่ (ROP)', '### จุดประสงค์
เพื่อให้นักศึกษาสามารถออกแบบโครงสร้างรหัสสินค้า (SKU) สร้างบัญชีคุมสต็อก และคำนวณจุดสั่งซื้อใหม่ (Reorder Point) จากโจทย์ธุรกิจจริงได้อย่างถูกต้อง แม่นยำ

### ขั้นตอนการปฏิบัติงาน
1. สมมุติสินค้า 1 ตระกูลที่มีความหลากหลาย (เช่น เสื้อโปโล 3 สี 4 ไซส์ รวม 12 รูปแบบ หรือ เครื่องสำอาง 4 เฉดสี)
2. ออกแบบโครงสร้างรหัสสินค้า **SKU System** ให้ครอบคลุมทุกรูปแบบ พร้อมจัดทำตารางรายการสินค้า (SKU Master List)
3. จัดทำตัวอย่างแบบฟอร์ม **Stock Card** สำหรับสินค้า 1 SKU พร้อมจำลองรายการรับเข้า-จ่ายออก อย่างน้อย 5 รายการตามหลัก FIFO
4. แก้โจทย์การคำนวณการสั่งซื้อ:
   - กำหนดยอดขายเฉลี่ยต่อวัน (D)
   - ระยะเวลาการสั่งผลิตและจัดส่ง (Lead Time: L)
   - สต็อกสำรองเพื่อความปลอดภัย (Safety Stock: SS)
   - แสดงวิธีทำและคำนวณหาค่าจุดสั่งซื้อใหม่ (Reorder Point: ROP) อย่างละเอียด
5. เสนอกลยุทธ์ในการระบายสินค้าค้างสต็อก (Dead Stock) สำหรับร้านค้านี้อย่างน้อย 2 วิธีการ
6. จัดทำเป็นรายงาน PDF แนบส่งในระบบ (ไม่เกิน 10 MB)', 20, '[{"criterion":"ความถูกต้องและเป็นระบบของโครงสร้างรหัสสินค้า (SKU)","max":5,"description":"ตั้งรหัสสินค้าได้อย่างเป็นระบบ สื่อความหมายชัดเจน ครอบคลุมทุกตัวเลือกสินค้า"},{"criterion":"ความถูกต้องของ Stock Card และหลักการ FIFO","max":5,"description":"บันทึกรายการรับเข้า จ่ายออก และคำนวณยอดคงเหลือใน Stock Card ได้ถูกต้องตามหลักการ"},{"criterion":"ความแม่นยำในการคำนวณจุดสั่งซื้อใหม่ (ROP) และ Safety Stock","max":5,"description":"แสดงสูตร วิธีทำ และคำนวณตัวเลขได้อย่างแม่นยำ พร้อมอธิบายความหมายทางธุรกิจได้ถูกต้อง"},{"criterion":"ความสมบูรณ์ของกลยุทธ์ระบายสต็อกและการจัดรูปเล่ม","max":5,"description":"มีแนวคิดระบายสต็อกที่ทำได้จริง รูปเล่มเรียบร้อย สวยงาม และส่งงานตรงต่อเวลา"}]'::jsonb
FROM public.units u WHERE u.number = 6;

-- Unit 7: การจัดอันดับเว็บไซต์และการค้นหา (SEO) สำหรับการค้าออนไลน์
INSERT INTO public.units (number, title, description, objectives, published)
VALUES (7, 'การจัดอันดับเว็บไซต์และการค้นหา (SEO) สำหรับการค้าออนไลน์', 'การค้นหาคำหลัก (Keywords), On-page SEO, การเขียนหัวข้อและคำบรรยายสินค้า, Marketplace Search (Shopee/TikTok), Social SEO และ Google Business Profile', ARRAY['อธิบายหลักการทำงานของ Search Engine และอัลกอริทึมการค้นหาบนแพลตฟอร์มต่างๆ ได้', 'วิเคราะห์และคัดเลือกคำค้นหาหลัก (Keywords) ที่มีประสิทธิภาพสำหรับกลุ่มลูกค้าเป้าหมาย', 'ปรับแต่งชื่อสินค้า คำบรรยาย และแฮชแท็กตามหลัก SEO บน Social Commerce และ Marketplace', 'ประยุกต์ใช้ Local SEO (Google Business Profile) เพื่อเพิ่มยอดขายหน้าร้านและความน่าเชื่อถือด้วยความรอบคอบ'], true)
ON CONFLICT (number) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  objectives = EXCLUDED.objectives,
  published = true;

INSERT INTO public.lessons (unit_id, position, title, content_md)
SELECT u.id, 1, 'หลักการค้นหาและเครื่องมือวิจัยคีย์เวิร์ด (Keyword Research)', '## ความสำคัญของการค้นหาในยุค Social Commerce

ผู้บริโภคยุคใหม่ไม่ได้ค้นหาสินค้าผ่าน Google เพียงอย่างเดียว แต่ค้นหาโดยตรงบน **Shopee, TikTok, Instagram และ Facebook** การทำ SEO จึงไม่ใช่แค่การทำเว็บไซต์ แต่คือการทำให้สินค้าของคุณถูกค้นพบในทุกช่องทาง

### ประเภทของคำค้นหา (Keyword Types)
1. **Short-tail Keywords (คำค้นหากว้าง):** เช่น "เสื้อผ้า", "เค้ก" — มีปริมาณการค้นหาสูงมาก แต่อัตราการซื้อต่ำ (Low Conversion) เพราะความต้องการยังไม่ชัดเจน และการแข่งขันสูงมาก
2. **Long-tail Keywords (คำค้นหาเจาะจง):** เช่น "เสื้อยืดโอเวอร์ไซส์ คอตตอน 100% สีขาว", "เค้กมะพร้าวอ่อน เกาะสมุย ส่งด่วน" — มีปริมาณการค้นหาปานกลาง แต่ **อัตราการตัดสินใจซื้อสูงมาก (High Conversion)** เพราะตรงกับความต้องการเฉพาะตัว
3. **Intent-based Keywords (คำค้นหาที่แสดงความพร้อมซื้อ):** คำที่มีคำว่า "ราคา", "พร้อมส่ง", "โปรโมชัน", "รีวิว", "ของแท้"

### เครื่องมือและเทคนิคการค้นหาคีย์เวิร์ดภาษาไทย
- **Search Auto-complete:** สังเกตคำค้นหาแนะนำที่ระบบเด้งขึ้นมาเมื่อเริ่มพิมพ์ลงในช่องค้นหาของ TikTok, Shopee หรือ Google
- **Google Trends:** ตรวจสอบความสนใจตามฤดูกาลและเปรียบเทียบคำค้นหาในไทย
- **แท็กและหัวข้อที่กำลังมาแรง (Trending Topics / Hashtags):** ดูใน TikTok Creative Center หรือ Meta Business Suite

> 💡 เคล็ดลับ: รวมคำค้นหาที่เป็นภาษาพูดและคำทับศัพท์ที่คนไทยนิยมใช้ เช่น "มินิมอล", "เกาหลี", "กันน้ำ", "ชาร์จเร็ว" ไว้ในชื่อสินค้าจะช่วยเพิ่มโอกาสถูกค้นพบ

> ⚠️ ข้อควรระวัง (ความละเอียด รอบคอบ): ห้ามทำ **Keyword Stuffing** (การยัดคำค้นหาซ้ำๆ ที่ไม่เกี่ยวข้องกันลงในโพสต์) เช่น "เสื้อ กางเกง กระเป๋า รองเท้า..." เพราะอัลกอริทึมจะลดการมองเห็น และทำให้ผู้ซื้อรู้สึกว่าร้านค้าไม่มีคุณภาพ'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.lessons (unit_id, position, title, content_md)
SELECT u.id, 2, 'เทคนิค On-page SEO และการปรับแต่งชื่อสินค้าบน Marketplace & Social Media', '## สูตรการตั้งชื่อสินค้าให้ติดอันดับการค้นหา

ชื่อสินค้า (Product Title) คือปัจจัยที่มีน้ำหนักต่อการจัดอันดับมากที่สุดของทั้ง Search Engine และ Marketplace

### สูตรโครงสร้างชื่อสินค้ามาตรฐาน (Title Formula)
$$\text{ชื่อสินค้า} = [\text{แบรนด์}] + [\text{ประเภทสินค้า}] + [\text{รุ่น/คุณสมบัติเด่น}] + [\text{วัสดุ/ขนาด/สี}] + [\text{จุดขายพิเศษ/การรับประกัน}]$$

#### ตัวอย่างการเปรียบเทียบ:
- **แบบเดิมที่ไม่ดี:** `รองเท้าผ้าใบสวยๆ ราคาถูก` (กว้างเกินไป ขาดคีย์เวิร์ดสำคัญ)
- **แบบที่ปรับแต่งตามหลัก SEO:** `[K-Step] รองเท้าผ้าใบผู้หญิง เสริมส้น 2 นิ้ว สไตล์เกาหลี น้ำหนักเบา ระบายอากาศ ไซส์ 36-40 พร้อมส่ง`

### การปรับแต่งคำบรรยายสินค้า (Product Description SEO)
1. **ย่อหน้าแรก (First 150 words):** ใส่คีย์เวิร์ดหลักและสรุปจุดเด่นของสินค้าอย่างเป็นธรรมชาติ
2. **โครงสร้างหัวข้อย่อยและกระสุนข้อความ (Bullet Points):** ช่วยให้อัลกอริทึมและผู้ใช้งานอ่านข้อมูลได้อย่างรวดเร็ว
3. **การแท็กรูปภาพ (Alt Text / File Name):** ตั้งชื่อไฟล์ภาพสินค้าให้มีคีย์เวิร์ด เช่น `sneakers-women-white-01.jpg` แทนที่จะเป็น `IMG_001.jpg`

> 💡 เคล็ดลับ: สำหรับแพลตฟอร์ม Social Media อย่าง TikTok และ Instagram เสียงพูดในคลิป (Voice Transcription) และข้อความที่วางบนหน้าจอวิดีโอ (Captions) ถูกนำมาประมวลผลเป็นคีย์เวิร์ดค้นหาด้วยเช่นกัน

> ⚠️ ข้อควรระวัง (ความละเอียด รอบคอบ): อย่าใส่ชื่อแบรนด์ดังที่ไม่เกี่ยวข้องกับสินค้าของคุณ เช่น ขายเสื้อยืดธรรมดาแต่ใส่คำว่า "สไตล์ Uniqlo / Nike" เพราะอาจถูกระบบตรวจจับการละเมิดทรัพย์สินทางปัญญาและถูกแบนบัญชีทันที'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.lessons (unit_id, position, title, content_md)
SELECT u.id, 3, 'Social SEO, การใช้แฮชแท็ก และ Local SEO (Google Business Profile)', '## การเชื่อมโยงการค้นหาบนโลกโซเชียลกับธุรกิจท้องถิ่น

SEO ในยุคปัจจุบันครอบคลุมถึงการดึงดูดลูกค้าในพื้นที่ (Local Area) และการใช้ฟังก์ชันค้นหาของแพลตฟอร์มโซเชียลมีเดีย

### 1. กลยุทธ์ Social SEO และแฮชแท็ก (#Hashtags)
- **แฮชแท็กแบรนด์ (#BrandHashtag):** เช่น `#ชื่อร้านค้า` เพื่อรวบรวมเนื้อหาและรีวิวของลูกค้า
- **แฮชแท็กหมวดหมู่สินค้า (#CategoryHashtags):** เช่น `#เสื้อยืดโอเวอร์ไซส์` `#ของแต่งห้องมินิมอล`
- **แฮชแท็กสถานที่หรือกลุ่มเป้าหมาย:** เช่น `#ของกินสมุย` `#เด็กปวส`
- **ปริมาณที่เหมาะสม:** แพลตฟอร์มส่วนใหญ่แนะนำให้ใช้แฮชแท็กที่ตรงประเด็น 3–5 แท็ก แทนการใส่แท็กหลายสิบแท็กที่ไร้ประโยชน์

### 2. Local SEO ด้วย Google Business Profile (GBP)
สำหรับร้านค้าออนไลน์ที่มีหน้าร้านจริง จุดรับสินค้า หรือให้บริการในพื้นที่เฉพาะ เช่น ธุรกิจบนเกาะสมุย สุราษฎร์ธานี:
- **ปักหมุดตำแหน่งที่ตั้งอย่างแม่นยำบน Google Maps**
- ระบุหมวดหมู่ธุรกิจ เวลาเปิด-ปิด เบอร์โทรศัพท์ และลิงก์ไปยังเพจ Facebook / LINE OA
- โพสต์ภาพบรรยากาศร้านค้า ภาพสินค้า และอัปเดตโปรโมชันอย่างสม่ำเสมอ
- ขอรีวิว 5 ดาวจากลูกค้าที่มาใช้บริการจริงพร้อมคำแนะนำที่ประทับใจ

> 💡 เคล็ดลับ: การสะสมรีวิวเชิงบวกบน Google Business Profile ที่มีคีย์เวิร์ดของสินค้า จะทำให้ธุรกิจของคุณติดอันดับ 1 ใน 3 (Local 3-Pack) เมื่อคนในพื้นที่ค้นหาคำว่า "...ใกล้ฉัน (Near me)"

> ⚠️ ข้อควรระวัง (ความละเอียด รอบคอบ): ตรวจสอบชื่อ ที่อยู่ และเบอร์โทรศัพท์ (NAP: Name, Address, Phone) ให้ตรงกันทุกช่องทาง (ทั้งบน Facebook, Website, Google Maps) เพราะข้อมูลที่ไม่ตรงกันจะลดความน่าเชื่อถือของคะแนน SEO'
FROM public.units u WHERE u.number = 7;

INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'Long-tail Keywords แตกต่างจาก Short-tail Keywords อย่างไรในแง่ของการทำการค้าออนไลน์?', '["มีคนค้นหามากกว่า 100 เท่า","เป็นคำค้นหาที่ยาวและเจาะจง แม้คนค้นหาจะน้อยกว่าแต่มีโอกาสตัดสินใจซื้อสูงกว่า (Higher Conversion)","ใช้ภาษาอังกฤษเท่านั้น","ต้องจ่ายเงินค่าคลิกแพงที่สุด"]'::jsonb, 1, 'Long-tail Keywords แสดงถึงความต้องการที่ชัดเจนและเฉพาะเจาะจง จึงมีโอกาสปิดการขายได้สูงกว่าคำกว้างๆ'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'โครงสร้างการตั้งชื่อสินค้า (Product Title) ที่ดีตามหลัก SEO บน Marketplace ควรประกอบด้วยสิ่งใด?', '["คำอุทานและอีโมจิ 20 ตัว","ชื่อแบรนด์ + ประเภทสินค้า + คุณสมบัติเด่น/วัสดุ + ขนาด/สี + จุดขายสำคัญ","เขียนเฉพาะรหัสสินค้าลับของร้าน","คัดลอกชื่อสินค้าของคู่แข่งมาทั้งประโยค"]'::jsonb, 1, 'โครงสร้างที่ดีต้องมีข้อมูลสำคัญครบถ้วนเพื่อตอบโจทย์ทั้งการจัดอันดับของระบบและการอ่านของผู้ซื้อ'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'พฤติกรรม ''Keyword Stuffing'' ในการเขียนรายละเอียดสินค้า ส่งผลเสียอย่างไร?', '["ทำให้ร้านค้าติดอันดับ 1 บน Google ทันที","ทำให้อัลกอริทึมลดการมองเห็นและผู้ซื้อรู้สึกว่าไม่มีคุณภาพ ขัดต่อหลักเกณฑ์ที่ดี","ทำให้ระบบจ่ายเงินทำงานเร็วขึ้น","ทำให้รูปภาพสินค้าคมชัดขึ้น"]'::jsonb, 1, 'การยัดคีย์เวิร์ดซ้ำซ้อนโดยไม่มีสาระถูกมองว่าเป็น Spam และถูกลงโทษโดยอัลกอริทึมค้นหา'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'คำค้นหาในข้อใดจัดเป็น Intent-based Keyword ที่แสดงความพร้อมในการซื้อสินค้ามากที่สุด?', '["ประวัติศาสตร์ของกาแฟ","เมล็ดกาแฟอาราบิก้า คั่วกลาง เชียงราย ราคา พร้อมส่ง","รูปภาพต้นกาแฟ","ชนิดของกาแฟในโลก"]'::jsonb, 1, 'มีคำบ่งชี้ความต้องการเฉพาะเจาะจง (สายพันธุ์, ระดับคั่ว, แหล่งผลิต) และคำกระตุ้นซื้อ (ราคา, พร้อมส่ง)'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ในการค้นหาบน TikTok นอกเหนือจากข้อความในแคปชัน อัลกอริทึมนำสิ่งใดมาประมวลผลเป็นคีย์เวิร์ดค้นหาด้วย?', '["ระดับแบตเตอรี่ของโทรศัพท์ผู้โพสต์","เสียงพูดในคลิป (Voice Transcription) และข้อความตัวอักษรที่ปรากฏบนวิดีโอ","ความเร็วของสัญญาณ Wi-Fi","สีของเคสโทรศัพท์"]'::jsonb, 1, 'ระบบ AI ของ TikTok แปลงเสียงพูดในวิดีโอและตัวหนังสือบนหน้าจอมาเป็นข้อมูลเพื่อจัดอันดับการค้นหา'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การใส่ข้อมูล Alt Text (Alternative Text) ให้กับภาพสินค้า มีประโยชน์หลักด้านใดสำหรับ SEO?', '["ช่วยเปลี่ยนสีรูปภาพให้อัตโนมัติ","ช่วยให้ Search Engine เข้าใจเนื้อหาของภาพว่าคืออะไร และช่วยผู้พิการทางสายตาเข้าถึงเนื้อหาได้","ช่วยให้ภาพเคลื่อนไหวได้","ช่วยลดขนาดกล่องพัสดุ"]'::jsonb, 1, 'Alt Text ทำหน้าที่บรรยายภาพเพื่อให้บอทค้นหาเข้าใจและเพิ่มโอกาสติดการค้นหาหมวดรูปภาพ'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'Google Business Profile (GBP) มีบทบาทสำคัญอย่างยิ่งต่อการตลาดออนไลน์ประเภทใด?', '["การส่งสินค้าไปต่างประเทศ","Local SEO เพื่อดึงดูดลูกค้าในพื้นที่ใกล้เคียงและสร้างความน่าเชื่อถือบน Google Maps","การเขียนโปรแกรมคอมพิวเตอร์","การผลิตกล่องกระดาษ"]'::jsonb, 1, 'GBP ช่วยให้ธุรกิจท้องถิ่นปรากฏบน Google Search และ Maps เมื่อลูกค้าค้นหาร้านค้าในบริเวณใกล้เคียง'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'หลักการ NAP ในการทำ Local SEO หมายถึงข้อมูลสำคัญ 3 สิ่งใดที่ต้องตรงกันในทุกช่องทาง?', '["New, Active, Popular","Name (ชื่อ), Address (ที่อยู่), Phone (เบอร์โทรศัพท์)","Network, Account, Password","National, Area, Province"]'::jsonb, 1, 'NAP คือ Name, Address, Phone ที่ต้องถูกต้อง สม่ำเสมอ และตรงกันทุกแพลตฟอร์ม'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'เหตุใดจึงไม่ควรใส่ชื่อแบรนด์อื่นที่ตนเองไม่ได้ขาย (เช่น ใส่ ''สไตล์ Zara'' ทั้งที่ขายเสื้อโนแบรนด์) ลงในชื่อสินค้า?', '["เพราะจะทำให้ราคาขายลดลง","เพราะเสี่ยงต่อการถูกระงับบัญชีจากการละเมิดเครื่องหมายการค้าและหลอกลวงผู้บริโภค","เพราะลูกค้าจะจำชื่อแบรนด์ไม่ได้","เพราะภาพจะเบลอ"]'::jsonb, 1, 'การแอบอ้างชื่อเครื่องหมายการค้าของผู้อื่นผิดกฎหมายทรัพย์สินทางปัญญาและนโยบายแพลตฟอร์มอย่างร้ายแรง'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การใช้แฮชแท็ก (#) บน Social Media ควรมีลักษณะอย่างไรจึงจะเกิดประโยชน์สูงสุดต่อการค้นหา?', '["ใส่แฮชแท็กให้เต็มขีดจำกัด 100 คำ","เลือกแฮชแท็กที่ตรงกับเนื้อหา แบรนด์ และกลุ่มเป้าหมายประมาณ 3–5 แท็กอย่างมีคุณภาพ","ใช้เฉพาะภาษาละตินโบราณ","ใช้แฮชแท็กที่ไม่มีใครเคยใช้มาก่อนเลย"]'::jsonb, 1, 'การใช้แฮชแท็กที่ตรงประเด็นในจำนวนที่เหมาะสมช่วยให้อัลกอริทึมจัดหมวดหมู่คลิปหรือโพสต์ได้แม่นยำที่สุด'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'Google Trends มีประโยชน์อย่างไรสำหรับผู้ประกอบการร้านค้าออนไลน์?', '["ช่วยจ่ายเงินค่าสินค้าแทนลูกค้า","ช่วยวิเคราะห์แนวโน้มความนิยมและเปรียบเทียบความสนใจของคำค้นหาในช่วงเวลาและพื้นที่ต่างๆ","ช่วยพิมพ์สติกเกอร์บาร์โค้ด","ช่วยโทรตามลูกค้า"]'::jsonb, 1, 'Google Trends แสดงข้อมูลสถิติความสนใจของคำค้นหาในแต่ละช่วงเวลา ช่วยวางแผนสต็อกและโปรโมชัน'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การตั้งชื่อไฟล์รูปภาพก่อนอัปโหลดขึ้นร้านค้าออนไลน์ เช่น ''silk-shirt-blue.jpg'' ส่งผลดีต่อ SEO อย่างไร?', '["ช่วยให้คอมพิวเตอร์ไม่ติดไวรัส","ช่วยให้ Search Engine อ่านชื่อไฟล์และเข้าใจความเกี่ยวข้องกับคำค้นหาได้ดีขึ้นกว่าชื่อสุ่ม","ช่วยประหยัดหมึกพิมพ์","ช่วยให้ภาพหมุนได้รอบทิศทาง"]'::jsonb, 1, 'ชื่อไฟล์ที่สื่อความหมายเป็นสัญญาณหนึ่งที่ Search Engine ใช้จัดอันดับผลการค้นหารูปภาพ'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'คำว่า ''Conversion Rate'' ในบริบทของการค้นหาและการตลาดออนไลน์หมายถึงสิ่งใด?', '["อัตราการแลกเปลี่ยนเงินตราต่างประเทศ","สัดส่วนของผู้เข้าชมที่เปลี่ยนมาเป็นผู้ซื้อสินค้าจริงเทียบกับจำนวนผู้เข้าชมทั้งหมด","ความเร็วในการโหลดหน้าเว็บ","จำนวนครั้งที่ลูกค้ากดปุ่มย้อนกลับ"]'::jsonb, 1, 'Conversion Rate คือสัดส่วนร้อยละของผู้ที่มีพฤติกรรมเป้าหมาย (เช่น กดสั่งซื้อ) ต่อจำนวนผู้เข้าชมทั้งหมด'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การได้รับรีวิวเชิงบวกบน Google Business Profile หรือหน้าร้านค้าออนไลน์ ส่งผลต่อคะแนน SEO อย่างไร?', '["ไม่มีผลใดๆ ต่อการค้นหา","เพิ่มคะแนนความน่าเชื่อถือและความเกี่ยวข้อง ช่วยดันอันดับร้านค้าให้อยู่ในกลุ่มแรกๆ","ทำให้ระบบหักค่าโฆษณาเพิ่ม","ทำให้หมุดบนแผนที่หายไป"]'::jsonb, 1, 'รีวิวที่มีคุณภาพและคะแนนสูงเป็นสัญญาณความไว้วางใจ (Trust Signal) ที่อัลกอริทึมใช้จัดอันดับต้นๆ'
FROM public.units u WHERE u.number = 7;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'พฤติกรรมใดแสดงถึงความละเอียด รอบคอบ ในการเขียนเนื้อหาและทำ SEO ให้กับร้านค้าออนไลน์?', '["ก๊อปปี้ข้อความจากคู่แข่งมาวางโดยไม่อ่าน","ตรวจสอบตัวสะกด ไวยากรณ์ ความถูกต้องของข้อมูลจำเพาะ และการจัดวางโครงสร้างคีย์เวิร์ดอย่างเป็นธรรมชาติ","ยัดคำค้นหาแปลกๆ ที่ไม่เกี่ยวกับสินค้าเพื่อให้คนคลิกเข้ามา","ตั้งราคาในชื่อสินค้าแต่ในตะกร้าใส่ราคาอื่น"]'::jsonb, 1, 'การตรวจสอบความถูกต้องของภาษา สเปกสินค้า และการวางคีย์เวิร์ดอย่างมีคุณภาพคือหัวใจของความรอบคอบ'
FROM public.units u WHERE u.number = 7;

