INSERT INTO public.assignments (unit_id, kind, title, instructions_md, max_score, rubric)
SELECT u.id, 'worksheet', 'ใบงานที่ 7: วิจัยคีย์เวิร์ดและออกแบบชื่อสินค้า-คำบรรยายตามหลัก SEO สำหรับหลายแพลตฟอร์ม', '### จุดประสงค์
เพื่อให้นักศึกษาสามารถค้นคว้าและวิเคราะห์คำค้นหา (Keywords) ออกแบบชื่อสินค้า และปรับแต่งรายละเอียดสินค้าตามหลัก SEO เพื่อเพิ่มโอกาสในการถูกค้นพบบนแพลตฟอร์ม Social Media และ Marketplace

### ขั้นตอนการปฏิบัติงาน
1. เลือกสินค้าจำลองหรือสินค้าของธุรกิจจริง 1 รายการ
2. ทำการวิจัยคำค้นหา (Keyword Research) และจัดทำตารางจำแนกคีย์เวิร์ด:
   - Short-tail Keywords (2 คำ)
   - Long-tail Keywords (อย่างน้อย 3 คำ)
   - Intent-based / Buying Keywords (อย่างน้อย 3 คำ)
3. ปฏิบัติการตั้ง **ชื่อสินค้า (Product Title)** ตามสูตรมาตรฐานสำหรับการลงขายบน Marketplace (Shopee/Lazada หรือ TikTok Shop)
4. เขียน **คำบรรยายสินค้า (Product Description)** ที่มีโครงสร้างถูกต้องตามหลัก SEO ประกอบด้วย:
   - ย่อหน้าเปิดพร้อมคีย์เวิร์ด
   - รายละเอียดสเปกและคุณประโยชน์
   - การเลือกแฮชแท็กที่เหมาะสม 5 แท็ก
5. กำหนดแนวทางการทำ **Local SEO** หรือปักหมุด Google Business Profile สำหรับร้านค้านี้
6. จัดทำเป็นรายงาน PDF แนบส่งในระบบ (ไม่เกิน 10 MB)', 20, '[{"criterion":"ความถูกต้องและคุณภาพของการวิจัยคำค้นหา (Keywords)","max":5,"description":"จำแนกประเภทคีย์เวิร์ดได้ถูกต้อง คำค้นหาสอดคล้องกับพฤติกรรมผู้บริโภคจริงในไทย"},{"criterion":"ความสมบูรณ์และถูกต้องของโครงสร้างชื่อสินค้าตามหลัก SEO","max":5,"description":"ตั้งชื่อสินค้าตามสูตรมาตรฐาน มีคีย์เวิร์ดสำคัญครบถ้วน ไม่ละเมิดกฎหมายหรือกฎชุมชน"},{"criterion":"ความละเอียด รอบคอบ ของคำบรรยายและแฮชแท็ก","max":5,"description":"เขียนเนื้อหาไหลลื่น ใช้ภาษาถูกต้อง โครงสร้างอ่านง่าย วางคีย์เวิร์ดและแฮชแท็กอย่างเป็นธรรมชาติ"},{"criterion":"รูปแบบการนำเสนอและความเป็นระเบียบเรียบร้อย","max":5,"description":"จัดทำรูปเล่มสวยงาม เป็นระเบียบ ชัดเจน และส่งตรงต่อเวลา"}]'::jsonb
FROM public.units u WHERE u.number = 7;

-- Unit 8: การใช้เครื่องมือดิจิทัลในธุรกิจพาณิชย์บนสื่อสังคมออนไลน์
INSERT INTO public.units (number, title, description, objectives, published)
VALUES (8, 'การใช้เครื่องมือดิจิทัลในธุรกิจพาณิชย์บนสื่อสังคมออนไลน์', 'เครื่องมือออกแบบและวิดีโอ (Canva/CapCut), Meta Business Suite, TikTok Ads, วิเคราะห์ข้อมูล (Meta Insights/GA4), แชทบอท และ Generative AI เพื่อการค้า', ARRAY['เลือกใช้เครื่องมือดิจิทัลสำหรับการผลิตสื่อกราฟิกและวิดีโอสั้นได้อย่างมีประสิทธิภาพ', 'อธิบายกระบวนการวางแผนเผยแพร่เนื้อหาและยิงโฆษณาผ่านระบบจัดการหลังบ้านได้', 'วิเคราะห์ข้อมูลเชิงลึก (Analytics & Insights) เพื่อประเมินผลการทำการตลาดออนไลน์ได้', 'ประยุกต์ใช้ปัญญาประดิษฐ์ (Generative AI) ช่วยสร้างสรรค์เนื้อหาด้วยความถูกต้อง ละเอียด รอบคอบ และมีจริยธรรม'], true)
ON CONFLICT (number) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  objectives = EXCLUDED.objectives,
  published = true;

INSERT INTO public.lessons (unit_id, position, title, content_md)
SELECT u.id, 1, 'เครื่องมือสร้างสรรค์เนื้อหาและวิดีโอสั้น (Canva, CapCut & Live Tools)', '## เครื่องมือดิจิทัลเพื่อการผลิตคอนเทนต์ที่ดึงดูดสายตา

ในยุคที่ความสนใจของผู้บริโภคสั้นลง (Short Attention Span) ภาพลักษณ์และคลิปวิดีโอที่น่าสนใจภายใน 3 วินาทีแรก (Hook) มีความสำคัญสูงสุดต่อยอดขาย

### 1. Canva สำหรับงานกราฟิกพาณิชย์
- การเลือกเทมเพลตให้เหมาะกับอัตราส่วนของแต่ละแพลตฟอร์ม: 1:1 สำหรับภาพโพสต์, 9:16 สำหรับ Story / Reels / TikTok, 16:9 สำหรับแนวนอน
- การใช้ชุดสีของแบรนด์ (Brand Kit) เพื่อสร้างการจดจำอัตลักษณ์แบรนด์ให้เป็นเอกภาพ
- เครื่องมือตกแต่งภาพสินค้า เช่น การลบพื้นหลัง (Background Remover) และการจัดวางเงาสินค้า

### 2. CapCut สำหรับการตัดต่อวิดีโอสั้น (Short-form Video)
- **3-Second Hook:** การวางจุดดึงดูดสายตาหรือปัญหาของลูกค้าไว้ใน 3 วินาทีแรกของคลิป
- **Auto-captions:** การใส่คำบรรยายอัตโนมัติภาษาไทย เพราะผู้ใช้ส่วนใหญ่เปิดดูคลิปโดยไม่เปิดเสียง
- **จังหวะและเสียงเพลงลิขสิทธิ์เชิงพาณิชย์:** เลือกใช้เพลงจาก Commercial Music Library ของแพลตฟอร์ม เพื่อป้องกันคลิปถูกปิดเสียงหรือโดนลบเนื่องจากละเมิดลิขสิทธิ์

### 3. อุปกรณ์และเครื่องมือสำหรับ Live Commerce
- ไฟสตูดิโอ (Ring Light หรือ Softbox) เพื่อให้แสงสว่างบนสินค้าชัดเจน
- ไมโครโฟนไร้สาย (Wireless Lavalier Mic) เพื่อเสียงพูดที่คมชัดไร้เสียงรบกวน
- ระบบกระดิ่งหรือเสียงเอฟเฟกต์กระตุ้นบรรยากาศความสนุกสนานในการไลฟ์

> 💡 เคล็ดลับ: ถ่ายทำวิดีโอสต็อก (B-roll) หลายๆ มุมเก็บไว้ เพื่อนำมาตัดต่อรีไซเคิลเป็นคอนเทนต์สั้นๆ ลงได้หลายช่องทาง

> ⚠️ ข้อควรระวัง (ความละเอียด รอบคอบ): ห้ามใช้ภาพถ่ายสินค้าของแบรนด์อื่นหรือภาพที่ติดลิขสิทธิ์มาใช้ในเชิงพาณิชย์โดยไม่ได้รับอนุญาต ตรวจสอบสิทธิ์การใช้งานฟอนต์และเพลงประกอบทุกครั้ง'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.lessons (unit_id, position, title, content_md)
SELECT u.id, 2, 'ระบบบริหารจัดการเนื้อหา โฆษณา และการวิเคราะห์ข้อมูล (Meta Suite, TikTok Ads & GA4)', '## การวางแผนและการวัดผลทางการตลาดดิจิทัล

การตลาดที่มีประสิทธิภาพต้องขับเคลื่อนด้วยข้อมูล (Data-driven Marketing) มากกว่าการคาดเดา

### 1. การจัดการเนื้อหาล่วงหน้าด้วย Meta Business Suite
- **Content Calendar:** ปฏิทินกำหนดการโพสต์เนื้อหาล่วงหน้าเป็นรายสัปดาห์หรือรายเดือน
- **Scheduling:** ตั้งเวลาโพสต์อัตโนมัติทั้งบน Facebook และ Instagram ในช่วงเวลาที่มีผู้ใช้งานสูงสุด (Peak Hours)
- **Unified Inbox:** รวมกล่องข้อความและคอมเมนต์จากทุกเพจมาตอบในหน้าต่างเดียว

### 2. พื้นฐานการยิงโฆษณาออนไลน์ (Meta Ads & TikTok Ads)
- **วัตถุประสงค์ของแคมเปญ (Campaign Objectives):** การรับรู้ (Awareness), การมีส่วนร่วม (Engagement), ข้อความแชท (Messages), หรือยอดขาย/คอนเวอร์ชัน (Conversions/Sales)
- **การกำหนดกลุ่มเป้าหมาย (Targeting):** ข้อมูลประชากร (เพศ อายุ ที่อยู่), ความสนใจ (Interests), และพฤติกรรม (Behaviors)
- **ตัวชี้วัดประสิทธิภาพโฆษณาที่สำคัญ:**
  - **CPC (Cost Per Click):** ต้นทุนต่อหนึ่งคลิก
  - **CTR (Click-Through Rate):** อัตราการคลิกดูเทียบกับจำนวนครั้งที่โฆษณาแสดงผล
  - **ROAS (Return on Ad Spend):** ผลตอบแทนจากค่าโฆษณา (ยอดขาย ÷ งบโฆษณา)

### 3. การวิเคราะห์ข้อมูลเชิงลึก (Analytics)
การอ่านกราฟพฤติกรรมผู้บริโภค เช่น ชั่วโมงที่คนเข้าดูมากที่สุด, ยอดวิวเฉลี่ย, และระยะเวลาเฉลี่ยที่คนดูวิดีโอ เพื่อนำมาปรับปรุงเนื้อหาในรอบถัดไป

> 💡 เคล็ดลับ: การทำ A/B Testing โดยทดสอบโฆษณา 2 ชิ้นที่เปลี่ยนเฉพาะรูปภาพปกหรือข้อความพาดหัว ช่วยค้นหาชิ้นงานที่ให้ผลลัพธ์คุ้มค่างบประมาณที่สุด

> ⚠️ ข้อควรระวัง (ความละเอียด รอบคอบ): ตรวจสอบการตั้งค่างบประมาณโฆษณา (Daily Budget vs Lifetime Budget) อย่างรอบคอบ การใส่ตัวเลขผิดพลาด (เช่น จะใส่ 500 บาท แต่ใส่ศูนย์เกินเป็น 5,000 บาทต่อวัน) จะสร้างความเสียหายทางการเงินอย่างรวดเร็ว'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.lessons (unit_id, position, title, content_md)
SELECT u.id, 3, 'ระบบแชทบอทอัตโนมัติ และการประยุกต์ใช้ Generative AI อย่างมีจริยธรรม', '## นวัตกรรมปัญญาประดิษฐ์และระบบอัตโนมัติเพื่อการค้า

เทคโนโลยี AI เข้ามาช่วยลดเวลาการทำงานของผู้ประกอบการเดี่ยว (Solopreneur) และทีมงานขนาดเล็กได้อย่างมหาศาล

### 1. ระบบตอบกลับอัตโนมัติและแชทบอท (Chatbots)
- **LINE OA Rich Menu & Quick Reply:** เมนูลัดที่ติดอยู่ด้านล่างจอแชท ช่วยให้ลูกค้ากดดูแคตตาล็อกสินค้า เช็กเลขพัสดุ หรือดูวิธีการสั่งซื้อได้ทันทีตลอด 24 ชั่วโมง
- **Chatbot ตอบคำถามตามคีย์เวิร์ด:** ตั้งเงื่อนไขให้บอทส่งข้อมูลเมื่อลูกค้าพิมพ์คำว่า "ราคา", "ขนาด", หรือ "เลขบัญชี"

### 2. การใช้งาน Generative AI ช่วยเขียนเนื้อหาและแคปชัน
เครื่องมืออย่าง ChatGPT, Claude หรือ Gemini สามารถช่วยงานได้หลากหลาย:
- คิดไอเดียคอนเทนต์ประจำสัปดาห์ (Content Brainstorming)
- ร่างข้อความแคปชันขายของตามเทคนิค AIDA (Attention, Interest, Desire, Action)
- เขียนสคริปต์พูดสำหรับการไลฟ์หรือคลิปสั้น
- ปรับสำนวนการตอบข้อความให้สุภาพและเป็นมืออาชีพ

### 3. จริยธรรมและความละเอียดรอบคอบในการใช้ AI
- **ความถูกต้องของข้อเท็จจริง (Fact-checking):** AI อาจสร้างข้อมูลที่ผิดพลาด (Hallucination) ผู้ประกอบการต้องตรวจสอบข้อมูลส่วนผสม ราคา สเปก และข้อกฎหมายด้วยตนเองเสมอก่อนเผยแพร่
- **ความเป็นมนุษย์และความจริงใจ:** ข้อความจาก AI มักดูแข็งทื่อ ขาดอารมณ์ความรู้สึก ควรปรับแต่งภาษาให้เป็นธรรมชาติและมีเอกลักษณ์ของแบรนด์

> 💡 เคล็ดลับ: การป้อนคำสั่ง (Prompt) ที่ดีต้องระบุ: บทบาทสมมุติ + กลุ่มเป้าหมาย + สินค้าและจุดขาย + โทนเสียงที่ต้องการ + รูปแบบผลลัพธ์ที่ต้องการ

> ⚠️ ข้อควรระวัง (ความละเอียด รอบคอบ): ห้ามป้อนข้อมูลความลับทางการค้า รหัสผ่าน หรือข้อมูลส่วนบุคคลของลูกค้า (PDPA) ลงในโปรแกรม Generative AI สาธารณะเด็ดขาด'
FROM public.units u WHERE u.number = 8;

INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'อัตราส่วนภาพและวิดีโอแบบใดที่เหมาะสมที่สุดสำหรับการโพสต์คลิปบน TikTok, Instagram Reels และ YouTube Shorts?', '["16:9 (แนวนอน)","9:16 (แนวตั้งเต็มจอ)","4:3 (โทรทัศน์โบราณ)","1:2 (แนวนอนยาว)"]'::jsonb, 1, 'วิดีโอสั้นบนมือถือใช้สัดส่วน 9:16 แนวตั้งเพื่อให้แสดงผลเต็มหน้าจอสมาร์ทโฟน'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'แนวคิด ''3-Second Hook'' ในการผลิตวิดีโอสั้นเพื่อการค้าออนไลน์ หมายถึงสิ่งใด?', '["การทำให้คลิปมีความยาวเพียง 3 วินาทีเท่านั้น","การนำเสนอจุดเด่น ปัญหา หรือภาพที่ดึงดูดความสนใจให้หยุดดูภายใน 3 วินาทีแรกของคลิป","การให้ผู้ชมกะพริบตาทุก 3 วินาที","การนับถอยหลัง 3 วินาทีก่อนปิดร้าน"]'::jsonb, 1, '3-Second Hook คือกลยุทธ์หยุดนิ้วโป้งของผู้ใช้งานไม่ให้ปัดผ่านภายใน 3 วินาทีแรก'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'เหตุใดจึงจำเป็นต้องใส่คำบรรยายอัตโนมัติ (Auto-captions) หรือตัวหนังสือบนวิดีโอขายสินค้า?', '["เพื่อบังคับให้ผู้ชมต้องอ่านหนังสือ","เพราะผู้ใช้งานโซเชียลมีเดียจำนวนมากดูคลิปขณะอยู่นอกบ้านโดยปิดเสียง การมีตัวหนังสือช่วยให้เข้าใจเนื้อหาได้ทันที","เพื่อให้วิดีโอมีขนาดไฟล์ใหญ่ขึ้น","เพื่อให้อัลกอริทึมเปลี่ยนเพลงประกอบให้อัตโนมัติ"]'::jsonb, 1, 'ผู้ใช้ส่วนใหญ่เปิดดูคลิปในที่สาธารณะแบบปิดเสียง คำบรรยายจึงช่วยสื่อสารข้อมูลสินค้าได้ครบถ้วน'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ข้อควรระวังสำคัญที่สุดในการตั้งงบประมาณโฆษณา (Budget) บน Meta Ads หรือ TikTok Ads คือข้อใด?', '["ห้ามใช้อินเทอร์เน็ตความเร็วสูง","ตรวจสอบตัวเลขและประเภทงบประมาณ (รายวัน Daily หรือ ตลอดอายุแคมเปญ Lifetime) ด้วยความรอบคอบเพื่อป้องกันการใช้เงินเกินงบ","ต้องใช้เงินอย่างน้อย 1 แสนบาทต่อวันเสมอ","ห้ามตั้งเวลาเริ่มโฆษณา"]'::jsonb, 1, 'ความประมาทในการใส่ตัวเลขหรือเลือกประเภทงบประมาณผิดอาจทำให้เสียค่าโฆษณาจำนวนมหาศาลเกินความตั้งใจ'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ดัชนีชี้วัด ROAS (Return on Ad Spend) มีสูตรการคำนวณอย่างไรและใช้บอกอะไร?', '["ยอดขายทั้งหมด ลบด้วย ต้นทุนสินค้า","ยอดขายที่ได้จากโฆษณา หารด้วย งบประมาณค่าโฆษณาที่ใช้ไป แสดงความคุ้มค่าของการยิงแอด","จำนวนคลิก หารด้วย จำนวนผู้ติดตาม","ค่าจัดส่งสินค้า คูณด้วย จำนวนพัสดุ"]'::jsonb, 1, 'ROAS = รายได้จากโฆษณา / ค่าโฆษณา ใช้บอกว่าเงินค่าโฆษณาทุกๆ 1 บาท สร้างรายได้กลับคืนมากี่บาท'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'หากยิงโฆษณาไป 1,000 บาท แล้วสร้างยอดขายกลับมาได้ 4,000 บาท ค่า ROAS มีค่าเท่ากับเท่าใด?', '["2 เท่า","3 เท่า","4 เท่า","40 เท่า"]'::jsonb, 2, '4,000 / 1,000 = 4 เท่า (หรือ 400%)'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'เครื่องมือ Content Calendar ในการจัดการสื่อสังคมออนไลน์มีประโยชน์หลักเพื่ออะไร?', '["ใช้ดูวันหยุดราชการประจำปี","ใช้วางแผน จัดตารางเวลา และควบคุมการผลิตเนื้อหาล่วงหน้าอย่างเป็นระบบ","ใช้คำนวณภาษีมูลค่าเพิ่ม","ใช้ตรวจสอบความเร็วคอมพิวเตอร์"]'::jsonb, 1, 'Content Calendar ช่วยให้การผลิตและโพสต์คอนเทนต์มีความต่อเนื่อง สม่ำเสมอ และตรงตามแผนกลยุทธ์'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ฟีเจอร์ Rich Menu ใน LINE Official Account มีประโยชน์อย่างไรต่อการค้าออนไลน์?', '["ช่วยสร้างรายได้จากการเล่นเกม","เป็นเมนูลัดรูปภาพด้านล่างหน้าแชท ช่วยให้ลูกค้ากดดูสินค้า แคตตาล็อก หรือเช็กพัสดุได้สะดวกตลอดเวลา","ช่วยแปลภาษาต่างประเทศอัตโนมัติ","ช่วยดาวน์โหลดเพลงฟรี"]'::jsonb, 1, 'Rich Menu ทำหน้าที่เหมือนหน้าแรกของเว็บไซต์ในแอป LINE ให้ลูกค้าเข้าถึงเมนูสำคัญได้ในคลิกเดียว'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การทดสอบโฆษณาแบบ A/B Testing มีจุดประสงค์เพื่ออะไร?', '["เพื่อจ่ายค่าโฆษณาสองเท่าให้แพลตฟอร์ม","เพื่อเปรียบเทียบประสิทธิภาพของตัวแปร 2 แบบ (เช่น รูปภาพต่างกัน หรือ พาดหัวต่างกัน) เพื่อหาชิ้นงานที่คุ้มค่าที่สุด","เพื่อสุ่มแจกของรางวัลให้พนักงาน","เพื่อทดสอบความเสถียรของสัญญาณไฟฟ้า"]'::jsonb, 1, 'A/B Testing คือการทดลองเปรียบเทียบเพื่อตัดสินใจโดยใช้ข้อมูลเชิงประจักษ์ (Data-driven decision)'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ข้อควรระวังเกี่ยวกับ ''ความละเอียด รอบคอบ'' ในการนำ Generative AI มาช่วยเขียนข้อความขายสินค้าคือข้อใด?', '["ห้ามใช้ AI เด็ดขาดเพราะผิดกฎหมายสากล","ต้องตรวจสอบความถูกต้องของข้อมูล สเปก และข้อเท็จจริง (Fact-checking) ก่อนเสมอ เพราะ AI อาจสร้างข้อมูลเท็จได้","ต้องให้ AI เป็นผู้ตัดสินใจตั้งราคาสินค้าเท่านั้น","ห้ามแก้ไขข้อความใดๆ ที่ AI เขียนให้"]'::jsonb, 1, 'AI มีโอกาสเกิด Hallucination (สร้างข้อมูลเท็จ) ผู้ใช้จึงต้องตรวจสอบข้อมูลอย่างละเอียดรอบคอบก่อนนำไปเผยแพร่จริง'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ข้อมูลประเภทใดที่ไม่ควรป้อนเข้าไปในระบบ Generative AI สาธารณะ (เช่น ChatGPT ฟรี)?', '["ไอเดียสีเสื้อผ้าแฟชั่น","ข้อมูลความลับทางการค้า รหัสผ่าน และข้อมูลส่วนบุคคลของลูกค้า (PDPA)","คำทักทายภาษาอังกฤษทั่วไป","ประวัติศาสตร์การค้าขายในสมัยโบราณ"]'::jsonb, 1, 'ข้อมูลความลับและข้อมูลส่วนบุคคลมีความเสี่ยงรั่วไหลสู่ภายนอกเมื่อป้อนเข้าสู่ระบบ AI สาธารณะ'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'เครื่องมือใดเหมาะสมที่สุดสำหรับการรวมกล่องข้อความแชทจากทั้ง Facebook Page และ Instagram ไว้ในที่เดียว?', '["Meta Business Suite (Unified Inbox)","Microsoft Excel","Notepad","เครื่องคิดเลข"]'::jsonb, 0, 'Meta Business Suite มีระบบกล่องข้อความรวมที่เชื่อมต่อแชทและคอมเมนต์จาก Facebook และ IG เข้าด้วยกัน'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การใช้เพลงประกอบในคลิปขายสินค้าบนแพลตฟอร์มโซเชียลมีเดีย ควรเลือกจากแหล่งใดจึงจะปลอดภัยจากการถูกระงับคลิป?', '["ดาวน์โหลดเพลงฮิตจากเว็บไซต์เถื่อน","คลังเพลงลิขสิทธิ์สำหรับการค้า (Commercial Music Library) ของแพลตฟอร์มนั้นๆ","อัดเสียงจากวิทยุรถยนต์","ใช้เพลงอะไรก็ได้โดยไม่ต้องกังวล"]'::jsonb, 1, 'การใช้คลิปเชิงพาณิชย์ต้องใช้เพลงในหมวด Commercial License เพื่อป้องกันการถูกฟ้องร้องหรือปิดเสียง'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ข้อใดคือองค์ประกอบสำคัญของการป้อนคำสั่ง (Prompt Engineering) ให้ AI ร่างข้อความขายของได้ตรงใจที่สุด?', '["พิมพ์เพียงคำว่า ''ช่วยขายของหน่อย''","ระบุบทบาท กลุ่มลูกค้า จุดเด่นสินค้า โทนภาษา และรูปแบบผลลัพธ์ที่ต้องการอย่างชัดเจน","พิมพ์ตัวพิมพ์ใหญ่ทั้งหมด","ใส่คำหยาบคายเพื่อให้ระบบตกใจ"]'::jsonb, 1, 'Prompt ที่ชัดเจนและมีบริบทครบถ้วนจะช่วยให้ AI สร้างคำตอบที่แม่นยำและตรงความต้องการมากที่สุด'
FROM public.units u WHERE u.number = 8;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ตัวชี้วัด CTR (Click-Through Rate) ในการยิงโฆษณามีความหมายว่าอย่างไร?', '["จำนวนเงินที่จ่ายไปทั้งหมด","สัดส่วนร้อยละของผู้ที่คลิกดูโฆษณาเทียบกับจำนวนครั้งที่โฆษณาแสดงผล (สะท้อนความน่าสนใจของภาพและข้อความ)","อัตราการคืนสินค้าของลูกค้า","จำนวนวันที่โฆษณาทำงาน"]'::jsonb, 1, 'CTR วัดความดึงดูดใจของชิ้นงานโฆษณา หาก CTR สูงแสดงว่าภาพและข้อความพาดหัวทำให้คนอยากคลิกดูต่อ'
FROM public.units u WHERE u.number = 8;

INSERT INTO public.assessments (kind, unit_id, title, unit_numbers, question_count, time_limit_minutes, max_attempts, is_open)
SELECT 'pretest', u.id, 'แบบทดสอบก่อนเรียน: ' || u.title, ARRAY[u.number], 10, NULL, 1, true
FROM public.units u WHERE u.number = 8
ON CONFLICT (kind, unit_id) DO UPDATE SET title = EXCLUDED.title, question_count = EXCLUDED.question_count;
INSERT INTO public.assessments (kind, unit_id, title, unit_numbers, question_count, time_limit_minutes, max_attempts, is_open)
SELECT 'posttest', u.id, 'แบบทดสอบหลังเรียน: ' || u.title, ARRAY[u.number], 10, 20, 3, true
FROM public.units u WHERE u.number = 8
ON CONFLICT (kind, unit_id) DO UPDATE SET title = EXCLUDED.title, question_count = EXCLUDED.question_count, max_attempts = EXCLUDED.max_attempts;

INSERT INTO public.assignments (unit_id, kind, title, instructions_md, max_score, rubric)
SELECT u.id, 'worksheet', 'ใบงานที่ 8: วางแผนปฏิทินเนื้อหา (Content Calendar) และออกแบบชิ้นงานสื่อดิจิทัลเพื่อการค้า', '### จุดประสงค์
เพื่อให้นักศึกษาสามารถวางแผนปฏิทินเนื้อหาการตลาดออนไลน์ ออกแบบสื่อกราฟิกด้วยเครื่องมือดิจิทัล และประยุกต์ใช้ Generative AI ช่วยงานอย่างมีจริยธรรมและความรอบคอบ

### ขั้นตอนการปฏิบัติงาน
1. กำหนดแบรนด์สินค้าและแคมเปญการตลาดประจำเดือน (เช่น แคมเปญต้อนรับเปิดเทอม หรือ แคมเปญลดกระหน่ำกลางเดือน)
2. จัดทำ **ปฏิทินเนื้อหา (Content Calendar)** สำหรับ 1 สัปดาห์ (7 วัน) ระบุ:
   - วัน/เวลาที่เผยแพร่
   - แพลตฟอร์มเป้าหมาย
   - วัตถุประสงค์ (เช่น ให้ความรู้, สร้างการมีส่วนร่วม, ปิดการขาย)
   - แนวคิดและธีมของเนื้อหา
3. ออกแบบ **ชิ้นงานสื่อดิจิทัล 1 ชิ้น** (ใช้ Canva หรือเครื่องมือที่ถนัด):
   - ภาพโพสต์โปรโมชัน หรือ ปกวิดีโอสั้น ขนาดเหมาะสมกับแพลตฟอร์ม
   - มีการจัดวางรูปภาพ ข้อความพาดหัว และองค์ประกอบแบรนด์อย่างสวยงาม
4. ทดลองใช้ **Generative AI** ช่วยเขียนแคปชันขายของ 1 โพสต์:
   - แนบภาพบันทึกหน้าจอคำสั่ง (Prompt) ที่ใช้
   - แนบข้อความที่ AI ตอบ และข้อความฉบับปรับปรุงแก้ไขด้วยฝีมือนักศึกษา (แสดงการตรวจสอบความถูกต้อง Fact-checking)
5. รวมเนื้อหาทั้งหมดเป็นรายงาน PDF หรือไฟล์ภาพ แนบส่งในระบบ (ไม่เกิน 10 MB)', 20, '[{"criterion":"ความสอดคล้องและเป็นระบบของปฏิทินเนื้อหา (Content Calendar)","max":5,"description":"วางแผนครอบคลุม 7 วัน มีวัตถุประสงค์ชัดเจน และกระจายเนื้อหาได้อย่างสมดุล"},{"criterion":"คุณภาพและความสวยงามของชิ้นงานสื่อดิจิทัล","max":5,"description":"ใช้ขนาดถูกต้อง ภาพคมชัด สื่อสารจุดขายได้ชัดเจน และมีการจัดองค์ประกอบที่ดี"},{"criterion":"ความละเอียด รอบคอบ ในการตรวจสอบและปรับแต่งผลลัพธ์จาก AI","max":5,"description":"แสดง Prompt ที่รัดกุม ตรวจสอบข้อเท็จจริง และปรับสำนวนภาษาได้อย่างเป็นมืออาชีพ"},{"criterion":"รูปแบบการนำเสนอและความเป็นระเบียบเรียบร้อย","max":5,"description":"จัดรูปเล่มสวยงาม เข้าใจง่าย เป็นระเบียบ และส่งตรงต่อเวลา"}]'::jsonb
FROM public.units u WHERE u.number = 8;

-- Unit 9: การวางแผนและประยุกต์ใช้พาณิชย์บนสื่อสังคมออนไลน์ทางธุรกิจ (โครงงาน)
INSERT INTO public.units (number, title, description, objectives, published)
VALUES (9, 'การวางแผนและประยุกต์ใช้พาณิชย์บนสื่อสังคมออนไลน์ทางธุรกิจ (โครงงาน)', 'การวิเคราะห์ตลาดและ SWOT, Business Model Canvas, การคำนวณโครงสร้างต้นทุนและราคาขาย, การวางแผนแคมเปญ, KPI, การจดทะเบียนพาณิชย์และภาษี e-Commerce', ARRAY['วิเคราะห์โอกาสทางการตลาด ลูกค้าเป้าหมาย (Persona) และจัดทำ Business Model Canvas ได้', 'คำนวณโครงสร้างต้นทุน กำไร และตั้งราคาขายที่ครอบคลุมค่าธรรมเนียมแพลตฟอร์มได้อย่างแม่นยำ', 'วางแผนแคมเปญการขายและกำหนดตัวชี้วัดความสำเร็จ (KPI) ทางธุรกิจออนไลน์ได้', 'ปฏิบัติการเปิดร้านค้าออนไลน์จริงบนสื่อสังคมออนไลน์ด้วยความละเอียด รอบคอบ และปฏิบัติตามกฎหมาย'], true)
