INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ตัวชี้วัด AOV (Average Order Value) ในธุรกิจอีคอมเมิร์ซ คำนวณได้อย่างไร?', '["รายได้รวมทั้งหมด หารด้วย จำนวนคำสั่งซื้อ (ออเดอร์) ทั้งหมด","ต้นทุนสินค้า หารด้วย จำนวนพนักงาน","ค่าโฆษณา หารด้วย จำนวนคลิก","จำนวนผู้ติดตาม หารด้วย จำนวนไลก์"]'::jsonb, 0, 'AOV = ยอดขายรวม / จำนวนออเดอร์ บอกยอดใช้จ่ายเฉลี่ยต่อตะกร้าของลูกค้า'
