INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'กลยุทธ์ใดช่วยเพิ่มค่า AOV (ยอดซื้อเฉลี่ยต่อคำสั่งซื้อ) ได้อย่างมีประสิทธิภาพ?', '["การลดราคาสินค้าทุกชิ้นลง 50%","การจัดโปรโมชันซื้อเป็นเซ็ต (Bundling) หรือกำหนดขั้นต่ำส่งฟรี (เช่น ซื้อครบ 500 บาท ส่งฟรี)","การจำกัดให้ซื้อได้คนละ 1 ชิ้นเท่านั้น","การปิดรับออเดอร์ในวันหยุด"]'::jsonb, 1, 'การตั้งเงื่อนไขส่งฟรีหรือการจัดเซ็ตสินค้าช่วยกระตุ้นให้ลูกค้าหยิบสินค้าเพิ่มขึ้นในหนึ่งคำสั่งซื้อ'
FROM public.units u WHERE u.number = 9;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'Buyer Persona มีประโยชน์อย่างไรในการเริ่มต้นวางแผนธุรกิจ Social Commerce?', '["ใช้สำหรับสมัครบัตรเครดิต","ช่วยจำลองภาพลูกค้าในอุดมคติอย่างลึกซึ้ง ทำให้เลือกช่องทาง สไตล์คอนเทนต์ และข้อความขายได้ตรงใจ","ช่วยเขียนโปรแกรมร้านค้า","ช่วยคำนวณภาษีมูลค่าเพิ่ม"]'::jsonb, 1, 'Persona ช่วยให้เข้าใจปัญหา พฤติกรรม และความต้องการของลูกค้า ทำให้วางกลยุทธ์ได้อย่างตรงเป้า'
FROM public.units u WHERE u.number = 9;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'ในช่วง Teasing Period ของแคมเปญใหญ่ (เช่น 11.11) ร้านค้าควรเน้นกิจกรรมใดมากที่สุด?', '["ปิดร้านและไปเที่ยวพักผ่อน","กระตุ้นให้ลูกค้ากดสินค้าเก็บลงตะกร้า (Add to cart) และเก็บโค้ดส่วนลดล่วงหน้า","ยกเลิกคำสั่งซื้อทั้งหมด","ขึ้นราคาสินค้า 3 เท่า"]'::jsonb, 1, 'ช่วง Teasing คือการเตรียมความพร้อมและสะสมความต้องการซื้อเพื่อให้เกิดยอดสั่งซื้อถล่มทลายในวัน D-Day'
FROM public.units u WHERE u.number = 9;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'เหตุใดร้านค้าออนไลน์ที่มียอดขายหลักล้านบาทจึงอาจประสบภาวะ ''ขาดทุน'' ได้หากขาดความรอบคอบ?', '["เพราะมีลูกค้ามากเกินไป","เพราะลืมนำค่าธรรมเนียมแพลตฟอร์ม ค่าโฆษณา ค่าบรรจุภัณฑ์ และอัตราของตีกลับมาคิดในต้นทุนจริง","เพราะระบบอินเทอร์เน็ตล่ม","เพราะธนาคารไม่ยอมรับเงินสด"]'::jsonb, 1, 'ต้นทุนแฝง เช่น ค่าธรรมเนียม ค่าการตลาด และพัสดุตีกลับ หากไม่นำมาคิดคำนวณอย่างรอบคอบจะทำให้กำไรหายหมด'
FROM public.units u WHERE u.number = 9;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'Business Model Canvas (BMC) มีช่องตารางหลักทั้งหมดกี่ช่องตามมาตรฐาน?', '["4 ช่อง","6 ช่อง","9 ช่อง","12 ช่อง"]'::jsonb, 2, 'BMC มีทั้งหมด 9 ช่ององค์ประกอบในการวิเคราะห์ภาพรวมธุรกิจ'
FROM public.units u WHERE u.number = 9;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การตั้งราคาขายสินค้าลงท้ายด้วยเลข 9 (เช่น 199 บาท แทน 200 บาท) เป็นการประยุกต์ใช้หลักการใด?', '["หลักการทางคณิตศาสตร์ชั้นสูง","หลักการจิตวิทยาการตั้งราคา (Psychological Pricing) ทำให้ผู้ซื้อรู้สึกว่าราคาถูกลงกว่าความเป็นจริง","หลักการลดภาษีเงินได้","หลักการจัดส่งพัสดุ"]'::jsonb, 1, 'เลข 9 ส่งผลต่อการรับรู้ทางจิตวิทยาของผู้บริโภค ทำให้รู้สึกว่าสินค้าอยู่ในช่วงราคาที่ต่ำกว่าหลักถัดไป'
FROM public.units u WHERE u.number = 9;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'สิ่งใดคือหลักฐานสำคัญที่ผู้ค้าออนไลน์ต้องจัดเก็บไว้อย่างรอบคอบเพื่อใช้ในการยื่นภาษีแบบหักค่าใช้จ่ายตามจริง?', '["ภาพถ่ายใบเสร็จค่าน้ำมันส่วนตัว","ใบกำกับภาษี ใบเสร็จรับเงิน และสลิปค่าใช้จ่ายที่เกี่ยวข้องกับกิจการอย่างถูกต้องครบถ้วน","บันทึกข้อความแชทคุยเล่นกับเพื่อน","ภาพถ่ายอาหารกลางวัน"]'::jsonb, 1, 'การหักค่าใช้จ่ายตามจริงต้องมีใบกำกับภาษีหรือใบเสร็จรับเงินที่ถูกต้องตามกฎหมายเพื่อเป็นหลักฐานอ้างอิง'
FROM public.units u WHERE u.number = 9;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'พฤติกรรมใดแสดงถึง ''เจตคติและกิจนิสัยที่ดีในการปฏิบัติงานด้วยความละเอียด รอบคอบ'' ของผู้ประกอบการออนไลน์?', '["ตรวจทานยอดเงิน คำนวณต้นทุนทุกบาททุกสตางค์ ทำบัญชีสม่ำเสมอ และปฏิบัติตามกฎหมายอย่างซื่อสัตย์","ตั้งราคาตามความรู้สึกโดยไม่คำนวณค่าธรรมเนียม","หลีกเลี่ยงการจดทะเบียนพาณิชย์และซ่อนรายได้","ส่งของช้าโดยไม่แจ้งเหตุผลให้ลูกค้าทราบ"]'::jsonb, 0, 'ความละเอียดรอบคอบครอบคลุมทั้งการเงิน การคำนวณ การบัญชี และความรับผิดชอบต่อกฎหมายและสังคม'
FROM public.units u WHERE u.number = 9;
INSERT INTO public.questions (unit_id, text, choices, answer_index, explanation)
SELECT u.id, 'การประเมินผลหลังจบแคมเปญการขาย (Post-campaign Review) มีประโยชน์ต่อธุรกิจอย่างไร?', '["เพื่อหาคนผิดมาลงโทษ","เพื่อวิเคราะห์ข้อมูลจริง เปรียบเทียบกับ KPI ค้นหาจุดแข็งและจุดที่ต้องปรับปรุงสำหรับแคมเปญครั้งต่อไป","เพื่อปิดกิจการทันที","เพื่อให้พนักงานหยุดงาน 1 เดือน"]'::jsonb, 1, 'การสรุปบทเรียนช่วยให้ธุรกิจเรียนรู้จากข้อมูลจริงและพัฒนาการดำเนินงานให้ดียิ่งขึ้นอย่างต่อเนื่อง'
FROM public.units u WHERE u.number = 9;

INSERT INTO public.assessments (kind, unit_id, title, unit_numbers, question_count, time_limit_minutes, max_attempts, is_open)
SELECT 'pretest', u.id, 'แบบทดสอบก่อนเรียน: ' || u.title, ARRAY[u.number], 10, NULL, 1, true
FROM public.units u WHERE u.number = 9
ON CONFLICT (kind, unit_id) DO UPDATE SET title = EXCLUDED.title, question_count = EXCLUDED.question_count;
INSERT INTO public.assessments (kind, unit_id, title, unit_numbers, question_count, time_limit_minutes, max_attempts, is_open)
SELECT 'posttest', u.id, 'แบบทดสอบหลังเรียน: ' || u.title, ARRAY[u.number], 10, 20, 3, true
FROM public.units u WHERE u.number = 9
ON CONFLICT (kind, unit_id) DO UPDATE SET title = EXCLUDED.title, question_count = EXCLUDED.question_count, max_attempts = EXCLUDED.max_attempts;

INSERT INTO public.assignments (unit_id, kind, title, instructions_md, max_score, rubric)
SELECT u.id, 'project', 'โครงงาน: วางแผนและเปิดร้านค้าบนสื่อสังคมออนไลน์จริง (Social Commerce Real-World Project)', '### จุดประสงค์โครงงาน
เพื่อให้นักศึกษาสามารถบูรณาการความรู้ ทักษะ และเจตคติจากทุกหน่วยการเรียนรู้ มาประยุกต์ใช้ในการวางแผน ออกแบบ เปิดร้านค้า และดำเนินธุรกิจบนสื่อสังคมออนไลน์จริงด้วยความละเอียด รอบคอบ

### ขอบเขตและระยะเวลาดำเนินการ (4 สัปดาห์)
- **สัปดาห์ที่ 1:** วิเคราะห์ตลาด กำหนดสินค้า กลุ่มเป้าหมาย จัดทำ Business Model Canvas (BMC) และคำนวณต้นทุน/ราคาขาย
- **สัปดาห์ที่ 2:** เปิดบัญชีร้านค้าจริง (เลือกอย่างน้อย 1 แพลตฟอร์ม เช่น TikTok Shop, Facebook Page + Shop, หรือ LINE SHOPPING), ออกแบบภาพและลงรายการสินค้าจริง
- **สัปดาห์ที่ 3:** ดำเนินการผลิตเนื้อหา เผยแพร่คอนเทนต์/คลิปสั้น/ไลฟ์สด ทดลองระบบชำระเงินและระบบจัดส่งสินค้า
- **สัปดาห์ที่ 4:** สรุปยอดขาย คำนวณผลการดำเนินงาน วิเคราะห์ KPI จัดทำรายงานฉบับสมบูรณ์ และนำเสนอผลงาน

### สิ่งที่ต้องส่งมอบในระบบ (Deliverables)
1. **ลิงก์หน้าร้านค้าออนไลน์จริง** (URL ของเพจ Facebook / ร้าน TikTok / LINE MyShop)
2. **รายงานสรุปโครงงานฉบับสมบูรณ์ (PDF ไม่เกิน 10 MB)** ประกอบด้วย:
   - แผนธุรกิจและ Business Model Canvas 9 ช่อง
   - ตารางแจกแจงโครงสร้างต้นทุนและสูตรคำนวณราคาขายจริง
   - ภาพถ่ายหลักฐานการตั้งค่าร้านค้าและการลงสินค้า
   - ภาพถ่ายหลักฐานการสื่อสารกับลูกค้า การรับชำระเงิน และการจัดส่งสินค้าจริง
   - ผลการดำเนินงานทางธุรกิจ (ยอดขาย, ต้นทุน, กำไรสุทธิ, KPI)
   - สรุปบทเรียน ปัญหาอุปสรรค และแนวทางการพัฒนาต่อยอด
   - รายการตรวจสอบความถูกต้องตามกฎหมาย (การจดทะเบียน, ภาษี, PDPA)', 100, '[{"criterion":"ความสมบูรณ์และถูกต้องของแผนธุรกิจและ Business Model Canvas","max":20,"description":"วิเคราะห์ตลาด กลุ่มเป้าหมาย และโมเดลธุรกิจ 9 ช่องได้อย่างมีหลักการ เป็นไปได้จริงทางธุรกิจ"},{"criterion":"ความแม่นยำในการคำนวณต้นทุน ราคาขาย และการบริหารการเงิน","max":20,"description":"แสดงสูตรคำนวณต้นทุนครบถ้วน รวมค่าธรรมเนียมและงบการตลาดอย่างละเอียดรอบคอบ ไม่ขาดทุน"},{"criterion":"คุณภาพการเปิดหน้าร้าน การลงรายการสินค้า และการผลิตสื่อดิจิทัล","max":20,"description":"หน้าร้านจริงมีความเป็นมืออาชีพ รูปภาพและคำบรรยายถูกต้องตามหลัก SEO สื่อดิจิทัลน่าสนใจ"},{"criterion":"การปฏิบัติงานจริงในระบบชำระเงิน การส่งสินค้า และบริการลูกค้า","max":20,"description":"มีหลักฐานการสนทนา การตรวจสอบสลิป การแพ็กส่ง และการบริการหลังการขายที่เป็นมืออาชีพ"},{"criterion":"ผลการประเมิน KPI ความละเอียดรอบคอบ และความถูกต้องตามกฎหมาย","max":20,"description":"วิเคราะห์ KPI อย่างตรงไปตรงมา ตรวจสอบกฎหมาย DBD/ภาษี/PDPA จัดรูปเล่มสมบูรณ์และส่งตรงเวลา"}]'::jsonb
FROM public.units u WHERE u.number = 9;

